  },
  Activity_116470_ActivityPlot = {
    Text = "Họ đã đi ngang qua số phận của nhau, chiếc đồng hồ tái khởi động đã quá muộn, chỉ còn lại trái tim hối hận, thề rằng sẽ chiếu sáng mọi thứ ô uế trong bóng tối."
