  Activity_119693_ActivityPlot = {
    Text = "Sau khi hoàn thành nhiệm vụ, có thể chọn 1 trong các Thể Đánh Thức giới hạn sau để đánh thức!"
  },
  Activity_119693_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, sau khi mỗi Người Giữ Bí Mật tích lũy sử dụng 200 lần Chìa Lệnh, có thể chọn 1 trong 8 Thể Đánh Thức SSR giới hạn để đánh thức, bao gồm Dung Hủy·Doll, Clementine, Chrysanthemum, Castor, Dulcein, Caligula, Pickman, Pollux.\n·Khi Người Giữ Bí Mật chọn Thể Đánh Thức đã được đánh thức, lần thứ 2~16 nhận được cùng Thể Đánh Thức SSR, mỗi lần sẽ chuyển đổi thành 1 Mảnh vỡ Thể Đánh Thức tương ứng và\"Kết Tủa Nguồn Gốc\" × 50; từ lần thứ 17 trở đi, Thể Đánh Thức SSR giới hạn sẽ chuyển đổi thành \"Mảnh Linh Hạch Tinh Túy\" × 2,\"Mảnh Linh Hạch\" × 6 và\"Kết Tủa Nguồn Gốc\" × 250."
  },
  Activity_119693_BannerText = {
    Text = "Nhận miễn phí Thể Đánh Thức giới hạn"
  },
  Activity_119694_ActivityName = {
    Text = "Sự Dẫn Lối của Sao Mai"
  },
  Activity_119694_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành chỉ định, có thể nhận phần thưởng tại \"Sự Dẫn Lối của Sao Mai\".\n·Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n·Lần này \"Kỷ Hành Cao Cấp\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 26 tháng 1(GMT+8).\n·Xin lưu ý: \"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Xin Người Giữ Bí Mật cân nhắc tiêu dùng hợp lý."
  },
  Activity_119694_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
  },
  Activity_119857_ActivityName = {
    Text = "Chúa Tể Trầm Ngủ"
  },
  Activity_119857_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Chúa Tể Trầm Ngủ\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Cthulhu, trải nghiệm không giới hạn các màn chơi được chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_120495_ActivityName = {
    Text = "Hồi Tưởng Hành Trình Hiến Lễ·Tinh Thần Thiên IV"
  },
  Activity_120495_ActivityPlot = {
    Text = "Một đoạn ký ức được niêm phong lưu trữ, một đoạn hành trình được ghi vào quá khứ. Khi truy tư, đừng quên dâng lên lễ vật kính ngưỡng."
  },
  Activity_120496_ActivityName = {
    Text = "Kỷ Hành Luân Hồi"
  },
  Activity_120496_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành được chỉ định, có thể nhận thưởng trong \"Kỷ Hành Luân Hồi\".\n2,\"Kỷ Hành Luân Hồi\" mở vĩnh viễn.\n3, Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4, Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Xin Người Giữ Bí Mật cân nhắc chi tiêu hợp lý."
  },
  Activity_120954_ActivityName = {
    Text = "Khúc ca ngợi của các vì sao"
  },
  Activity_122195_ActivityName = {
    Text = "Lễ tế hỏa trong vùng sương mù"
  },
  Activity_122195_ActivityPlot = {
    Text = "Ánh sáng của bình minh đang giải thể nỗi khổ của những tín đồ, những vì sao như chiếc thuyền, chở anh em đến vương quốc cao vời. \n Những chú cừu lạc lối đang hát múa nơi cửa, những ngọn nến sao trang trí cho thần đình vĩnh cửu. \n Nhưng sương mù sau cánh cửa đã sớm đáp lại lời gọi, sương mù ấy lừa dối, dối trá, chỉ để thỏa mãn sở thích biến dạng của chính nó. \n Sương mù đó vì vậy đã phong tỏa \"bình minh\", chặn đứng con đường tìm kiếm sự giải thoát. \n Cô sẽ ở đây, chứng kiến một lần nữa sự kết thúc của thế giới."
  },
  Activity_122195_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Căn nhà của Mộc Hạ\""
  },
  Activity_122195_ActivityTips = {
    Text = "<Title:Tổng quan hoạt động>\n1, Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ hoạt động \"tầm nhìn của sương mù\",\"giấc mơ của sương mù\",\"nguồn của sương mù\" thông qua các hoạt động giới hạn \"Mất tích bản thân\" và\"Phần thưởng thành tựu\". \"tầm nhìn của sương mù\",\"giấc mơ của sương mù\",\"nguồn của sương mù\" có thể được sử dụng để mua hàng hóa tại \"Căn nhà của Mouchette\", bao gồm vòng mệnh SR giới hạn hoạt động \"ánh đèn lý trí\", Lõi Lưu Minh, Hạt Nhân Sạch, v. v.\n2, Trong thời gian hoạt động,\"Kết nối đa chiều: Lễ rửa bạc và máu\" sẽ được mở khóa miễn phí trong thời gian giới hạn, hoàn thành thành tựu hoạt động còn có thể nhận được hình đại diện giới hạn hoạt động \"Tên của chìa khóa bạc: Mouchette\"!\n\n<Title:Thời gian hoạt động>\n1, Từ 9:00 ngày 29 tháng 12 đến 9:00 ngày 12 tháng 1(GMT+8), tất cả các hoạt động đều có thể tham gia.\n2, Từ 9:00 ngày 12 tháng 1 đến 9:00 ngày 19 tháng 1(GMT+8), chỉ có thể tham gia \"Căn nhà của Mouchette\" và phần thưởng thành tựu.\n\n<Title:Mất tích bản thân>\n1,\"Mất tích bản thân\" bao gồm 7 màn chơi, mỗi ngày tự động mở khóa 1 màn.\n2, Mỗi lần thách thức sẽ tiêu tốn \"Menophin\" × 120, thành công thách thức sẽ nhận được tiền tệ hoạt động.\n3, Sau khi hoàn thành màn chơi, sẽ mở khóa chức năng \"tái hiện\" của màn chơi đó. Xin lưu ý: khi sử dụng chức năng \"tái hiện\", sẽ không nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng sự trợ giúp của hội cựu sinh viên để giúp bạn dễ dàng hoàn thành màn chơi hơn.\n\n<Title:Căn nhà của Mouchette>\n \"Căn nhà của Mouchette\" có tổng cộng ba cửa hàng, thời gian mở cửa như sau:\n·\"Phòng vật liệu\": Mở cửa lúc 9 giờ ngày 29 tháng 12.\n·\"Nhập vào giấc mơ\": Mở cửa lúc 9 giờ ngày 30 tháng 12.\n·\"Phòng nuôi\": Mở cửa lúc 9 giờ ngày 31 tháng 12.\nTrong cửa hàng, bạn có thể chọn hàng hóa để mua trực tiếp.\n\n<Title:Hoạt động tăng cường>\n1, Người giữ bí mật sở hữu thân thể được đánh thức hoặc vòng mệnh cụ thể(không yêu cầu có mặt trong trận) có thể khiến phần thưởng nhiệm vụ trong màn chơi \"Mất tích bản thân\" là\"tầm nhìn của sương mù\",\"giấc mơ của sương mù\",\"nguồn của sương mù\" nhận được thêm phần thưởng rơi, cụ thể như sau:\n·Thân thể được đánh thức \"Mouchette\": Khởi linh 0/1/2/3 và trên, tăng cường 20%/30%/40%/50%.\n·Vòng mệnh SSR \"Mouchette\": Vị trí chồng 0/1/2/3 và trên, tăng cường 20%/30%/40%/50%.\n·Vòng mệnh SR \"ánh đèn lý trí\": Vị trí chồng 0/1/2/3 và trên, tăng cường 20%/30%/40%/50%.\n2, Các \"tăng cường hoạt động\" của các thân thể được đánh thức hoặc vòng mệnh khác nhau sẽ được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thách thức lần đầu độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"tăng cường hoạt động\".\n\n<Title:Kết nối đa chiều>\n1, Trong thời gian hoạt động,\"Kết nối đa chiều: Lễ rửa bạc và máu\" sẽ được mở khóa miễn phí.\n2, Sau khi kết thúc hoạt động, tiến trình điều tra của \"Kết nối đa chiều: Lễ rửa bạc và máu\" sẽ được giữ lại, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra giống như trong thời gian hoạt động. Nếu trong thời gian hoạt động chưa mở khóa \"Kết nối đa chiều: Lễ rửa bạc và máu\", sau khi kết thúc hoạt động vẫn có thể tiêu tốn \"điểm khởi đầu thực tế\" ×3 để mở khóa.\n3, Dù có trong thời gian hoạt động hay không, sau khi hoàn thành \"Kết nối đa chiều: Lễ rửa bạc và máu\" có thể nhận được \"Mật lệnh: Từ vùng sương mù\"."
  },
  Activity_122195_BannerText = {
    Text = "Sự kiện chơi game mở cửa trong thời gian giới hạn!"
