  Activity_124834_ActivityTips = {
    Text = "<Title:Quy tắc sự kiện>\n·Trong thời gian sự kiện \"Nhân Danh Sương Mù\", sau khi hoàn thành Chương 1 \"Bí mật Khu Đông\" của Hành động Điều tra, bạn có thể nhận miễn phí Thức Tỉnh Thể SSR giới hạn hoàn toàn mới \"Mạc Hạ\"!\n·Khi nhận được Thức Tỉnh Thể SSR giống nhau lần thứ 2~16, mỗi lần sẽ chuyển đổi thành 1 Mảnh vỡ Thức Tỉnh Thể tương ứng và\"Căn Nguyên Trầm Tích\" × 50; Từ lần thứ 17 trở đi, Thức Tỉnh Thể SSR giới hạn sẽ chuyển đổi thành \"Mảnh Tinh Túy Linh Hạch\" × 2,\"Mảnh Linh Hạch\" × 6 và\"Căn Nguyên Trầm Tích\" × 250."
