  Activity_124984_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Thi Thiên Vô Danh\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Aurla để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_124985_ActivityName = {
    Text = "Bệnh Nhân Phân Liệt·Biển Sâu"
  },
  Activity_124985_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Bệnh Nhân Phân Liệt·Biển Sâu\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm \"24\"để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_124986_ActivityName = {
    Text = "Bệnh Nhân Phân Liệt·Siêu Chiều"
  },
  Activity_124986_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Bệnh Nhân Phân Liệt·Siêu Chiều\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm \"24\"để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
