  Activity_126275_ActivityPlot = {
    Text = "Xa quay nhẹ xoay, vĩnh hằng không ngừng. Hãy khiêu vũ theo sợi tơ, hỡi người dệt vĩ đại. Số mệnh, là sân khấu mà ngươi không thể trốn thoát.\nKẻ phán xét. Kẻ cứu chuộc. Chủ nhân. Tù nhân…\nKhi bước chân lên sân khấu này, vai diễn thuộc về ngươi, từ lâu đã không còn lựa chọn."
