    Text = "Giám Mục Nhân Ái"
  },
  Activity_129706_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Giám Mục Nhân Ái\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Salvador để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
