  Activity_130176_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian mở\"Nhụy Nở Tình Yêu\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống thiết lập sẵn bao gồm Saya, trải nghiệm không giới hạn số lần tại màn chơi chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi đạt được thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
