  Activity_132688_ActivityName = {
    Text = "Di Chuyển Thông Tin"
  },
  Activity_132688_ActivityTips = {
    Text = "<Title:Giới thiệu hoạt động>\n 1, Sau khi Người Giữ Gìn hoàn thành nhiệm vụ chỉ định trong hoạt động, có thể nhận \"Lõi Lưu Minh\", ảnh đại diện giới hạn hoạt động \"Wenkel·Thiết bị đầu cuối lớn\", \"Erika·Thiết bị đầu cuối di động\" và \"Bộ sưu tập tem thư: Người giữ gìn\", cùng với trang phục ảo 1 sao mới \"Nốtira·Tiếng vang ren\", \"Hiro·Khoảnh khắc phá vỡ\" và các phần thưởng giới hạn hoạt động khác! \n 2, Hoạt động này mở vĩnh viễn. Sau khi hoàn thành tất cả nhiệm vụ trong hoạt động và nhận hết phần thưởng, hoạt động sẽ kết thúc và không còn hiển thị sau 9:00(GMT+8) ngày hôm sau.\n 3, Nếu trước đây đã hoàn thành nhiệm vụ \"Đăng nhập bằng thiết bị PC\" hoặc \"Đăng nhập bằng thiết bị di động\" trong tính năng phần thưởng đăng nhập, thì tại đây sẽ không được tính là hoàn thành lại."
  },
  Activity_132908_ActivityName = {
    Text = "Văn bản tạm thời"
