  Activity_139591_ActivityName = {
    Text = "\"Báo Ơn\" Của Mèo"
  },
  Activity_139591_ActivityPlot = {
    Text = "\"Thông báo khẩn cấp, toàn thể giáo viên và học sinh hãy lập tức dừng công việc hiện tại, hỗ trợ bắt giữ thể thí nghiệm đã trốn thoát.\"\n \"Nhắc lại một lần nữa, toàn thể giáo viên và học sinh hãy lập tức dừng công việc hiện tại, hỗ trợ bắt giữ đối tượng trốn... Chết tiệt! Lũ mèo đã vào rồi!\"\nKhi bạn nghe thấy giọng nói hoảng loạn trong loa phát thanh, toàn bộ học viện đã bị nhấn chìm trong lông đen, mọi người đang cuống cuồng bắt giữ những tên quỷ nhỏ trốn khỏi phòng thí nghiệm.\nDường như để trả thù cho lễ Kỳ Tuế, những con mèo đen đang chậm rãi và có trật tự tập trung về phía ký túc xá của bạn.\nNhưng mà... xét đến lượng lớn Kim Quyển và Ngân Tâm mà chúng mang theo, bạn khó mà nói được chúng đến để trả thù, hay là để\"báo ơn\".\nLưu ý, đừng đánh bắt quá mức nhé."
  },
  Activity_139591_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc"
  },
  Activity_139591_ActivityTips = {
    Text = "<Title: 「Báo Ơn」Của Mèo>\n·「Báo Ơn」Của Mèo bao gồm 7 màn chơi không thể tái hiện, thách đấu trực tiếp, mỗi ngày mở 1 màn.\n·Mỗi lần thách đấu chiến thắng「Mèo Đen Chiều Không Gian」tương ứng, sẽ tích lũy tiến độ nhiệm vụ, nhận phần thưởng tương ứng trong「Nhật Ký Bắt Mèo Đen」.\n·Mỗi loại「Mèo Đen Chiều Không Gian」đều có số lượng lớn phân thân, trong thời gian hoạt động có thể tham gia thách đấu không giới hạn số lần, thách đấu hỗ trợ chiến đấu tự động.\n·Mỗi màn chơi sẽ cung cấp các tạo vật khác nhau, mang đến cho bạn những tăng cường mạnh mẽ.\n·Tất cả màn chơi phải chọn trợ chiến, trong toàn bộ hoạt động, mỗi Người Giữ Bí Mật theo dõi lẫn nhau chỉ có thể cung cấp cho bạn một lần trợ chiến.\n\n<Title: Bù Cấp Độ>\n·Trong「Báo Ơn」Của Mèo có cơ chế bù cấp độ, để các Người Giữ Bí Mật có thể sát cánh chiến đấu!\nQuy tắc bù cấp độ như sau:\n  ·Trong đội điều tra, Thể Thức Tỉnh chưa đạt cấp 60 sẽ được bù lên cấp 60 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể Thức Tỉnh có cấp kỹ năng chưa đạt cấp 5 sẽ được bù lên cấp 5 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể Thức Tỉnh có「Điềm Báo Điên Cuồng」chưa đạt cấp 6 sẽ được bù lên cấp 6 trong lần thách đấu này.\n  ·Trong đội điều tra, Thể Thức Tỉnh có「Linh Tố Thích Tính」chưa đạt cấp 5 sẽ được bù lên cấp 5 trong lần thách đấu này.\n  ·Nếu cấp độ Người Giữ Bí Mật chưa đạt cấp 60, trong lần thách đấu này sẽ được bù lên cấp 60.\n\n<Title:Nhật Ký Bắt Mèo Đen>\n·Trong thời gian hoạt động, sau khi Người Giữ Bí Mật chiến thắng「Mèo Đen Chiều Không Gian」tương ứng, có thể tích lũy tiến độ nhiệm vụ tương ứng, nhận phần thưởng tương ứng trong「Nhật Ký Bắt Mèo Đen」, chia thành「Nhật Ký Bắt Cá Nhân」và「Nhật Ký Bắt Học Viện」.「Nhật Ký Bắt Cá Nhân」là nhiệm vụ cá nhân của Người Giữ Bí Mật.「Nhật Ký Bắt Học Viện」là nhiệm vụ của toàn bộ Người Giữ Bí Mật trong học viện.\n\n<Title:Bảng Xếp Hạng Bắt Giữ>\n·Trong thời gian hoạt động, Người Giữ Bí Mật có thể xem「Bảng Số Lần Bắt」và「Bảng Số Lần Hỗ Trợ」trong「Bảng Xếp Hạng Bắt Giữ」.\n\n<Title:Thời Gian Hoạt Động>\n· Trước 9:00 ngày 15 tháng 6 (GMT+8), Người Giữ Bí Mật có thể vào trang hoạt động để tham gia. Sau thời gian này sẽ không tiếp nhận Người Giữ Bí Mật mới tham gia thách đấu. Nếu hoạt động chưa kết thúc, Người Giữ Bí Mật đã tham gia có thể tiếp tục thách đấu.\n·Nếu đạt được「Tổng Số Bắt Giữ」trước 9:00 ngày 15 tháng 6 (GMT+8), hoạt động sẽ kết thúc vào 9:00 ngày 29 tháng 6 (GMT+8). Nếu chưa đạt「Tổng Số Bắt Giữ」trước 9:00 ngày 15 tháng 6 (GMT+8), hoạt động sẽ kết thúc sau 14 ngày kể từ khi đạt「Tổng Số Bắt Giữ」."
  },
