  Activity_141460_ActivityName = {
    Text = "Thánh Tử·Hắc Vũ"
  },
  Activity_141460_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Thánh Tử·Hắc Vũ\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Castor để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_141462_ActivityName = {
    Text = "Chúa Tể Trầm Ngủ"
  },
  Activity_141462_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Chúa Tể Trầm Ngủ\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Cthulhu, trải nghiệm không giới hạn các màn chơi được chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_141464_ActivityName = {
    Text = "Thiên Phiến Huyền Nữ"
  },
  Activity_141464_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Thiên Phiến Huyền Nữ\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Từ để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_141466_ActivityName = {
    Text = "Mở khóa miễn phí màn phụ"
  },
  Activity_141467_ActivityName = {
    Text = "Tù nhân gương·klon"
  },
  Activity_141467_ActivityPlot = {
    Text = "Chim bay à chim bay, tại sao chân bạn có xích bị gãy? \nChim bay à chim bay, tại sao bạn đơn độc hót trên không trung? \nVượt qua gai góc, trốn thoát khỏi cũi, bạn dang đôi cánh bay qua những cồn cát vàng rộng lớn, chỉ là tiếng hót buồn thương của bạn không từng ngừng lại. Ai mới là bạn đồng hành trung thành mà bạn đang tìm kiếm? Nơi nào mới là quê hương thực sự mà bạn đang tìm?"
  },
  Activity_141467_ActivityStageEndContent = {
    Text = "Hoạt động đã kết thúc, hiện tại chỉ có thể tham gia \"Nguyện vọng tri thức\""
  },
  Activity_141467_ActivityTips = {
    Text = "<Title:Giới thiệu hoạt động>\n1, Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ hoạt động \"Sách về sự thông minh\", \"Sách số học\", \"Sách văn học\" thông qua gameplay giới hạn thời gian \"Vượt bầu trời xanh\", \"Chuyến du lịch trong mơ\" và \"Phần Thưởng Thành Tựu\". \"Sách về sự thông minh\", \"Sách số học\", \"Sách văn học\" có thể dùng để mua hàng trong \"Khát vọng tri thức\", bao gồm vòng mệnh SR giới hạn hoạt động \"Lông vũ cô độc\", Lõi Lưu Minh, Hạt Nhân Sạch Will, v. v.\n2, Trong thời gian hoạt động, \"Thế giới Mộng Ảo: Sau đường chân trời·Trên\"được mở khóa miễn phí giới hạn thời gian, hoàn thành thành tựu hoạt động còn có thể nhận được avatar giới hạn hoạt động \"Tên của chìa khóa bạc: Cas-tơ-lơ\"!\n\n<Title:Thời gian hoạt động>\n1,9:00 ngày 5 tháng 10 - 9:00 ngày 2 tháng 11(GMT+8), tất cả gameplay hoạt động đều có thể tham gia.\n2,9:00 ngày 2 tháng 11 - 9:00 ngày 9 tháng 11(GMT+8), chỉ có thể tham gia \"Khát vọng tri thức\" và phần thưởng thành tựu.\n\n<Title:Vượt bầu trời xanh>\n1,\"Vượt bầu trời xanh\" bao gồm 7 màn chơi, mỗi 1 ngày tự động mở 1 màn.\n2, Mỗi lần thử thách sẽ tiêu tốn Menophin × 120, thử thách thành công sẽ nhận được tiền tệ hoạt động.\n3, Sau khi hoàn thành màn chơi, mở khóa chức năng \"Tái hiện\" của màn đó. Lưu ý: Khi sử dụng chức năng \"Tái hiện\", không thể nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng hỗ trợ chiến đấu của hội cựu sinh viên để giúp bạn vượt qua dễ dàng hơn.\n\n<Title: Khát vọng tri thức>\n\"Khát vọng tri thức\" có tổng cộng ba cửa hàng, thời gian mở như sau:\n·\"Khóa học tự chọn chung\": Mở lúc 9 giờ ngày 5 tháng 10.\n·\"Khóa học khoa học tự chọn\": Mở lúc 9 giờ ngày 6 tháng 10.\n·\"Khóa học văn học tự chọn\": Mở lúc 9 giờ ngày 7 tháng 10.\nTrong cửa hàng có thể chọn hàng hóa để mua trực tiếp.\n\n<Title:Tăng thêm hoạt động>\n1, Người giữ bí mật sở hữu Thể thức tỉnh hoặc vòng mệnh cụ thể(không yêu cầu đưa vào trận) có thể giúp \"Sách về sự thông minh\", \"Sách số học\", \"Sách văn học\" trong phần thưởng nhiệm vụ màn chơi \"Vượt bầu trời xanh\" nhận được tăng thêm rơi đồ, chi tiết như sau:\n·Thể thức tỉnh \"Cas-tơ-lơ\": khởi linh 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%.\n·Vòng mệnh SSR \"Tự do không thể chịu đựng nổi\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%.\n·Vòng mệnh SR \"Lông vũ cô độc\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%.\n2,\"Tăng thêm hoạt động\" của các Thể thức tỉnh hoặc vòng mệnh khác nhau được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thử thách lần đầu hoàn thành độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"Tăng thêm hoạt động\".\n\n<Title: Chuyến du lịch trong mơ>\n1, Mỗi giờ tự động nhận được 60 \"Sách về sự thông minh\", tối đa lưu trữ 25 giờ.\n\n<Title:Thế giới Mộng Ảo>\n1, Trong thời gian hoạt động, \"Thế giới Mộng Ảo: Sau đường chân trời·Trên\" có thể mở khóa miễn phí.\n2, Sau khi hoạt động kết thúc, tiến độ điều tra của \"Thế giới Mộng Ảo: Sau đường chân trời·Trên\" sẽ được giữ lại, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra giống như trong thời gian hoạt động. Nếu chưa mở khóa \"Thế giới Mộng Ảo: Sau đường chân trời·Trên\" trong thời gian hoạt động, sau khi hoạt động kết thúc vẫn có thể tiêu tốn \"điểm khởi đầu thực tế\" ×7 để mở khóa.\n3, Dù có trong thời gian hoạt động hay không, sau khi hoàn thành \"Thế giới Mộng Ảo: Sau đường chân trời·Trên\"đều có thể nhận được \"Mật lệnh: Sự sai lệch của số phận\"."
  },
