  },
  Activity_141509_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n1, Sau khi Người giữ bí mật hoàn thành nhiệm vụ hành trình được chỉ định, có thể nhận phần thưởng trong \"Nhật ký du hành bí cảnh\".\n2,\"Nhật ký du hành bí cảnh\" sẽ kết thúc vào lúc 09:00 ngày 27 tháng 7.\n3, Sau khi mở khóa \"Hành trình Cao cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4, Lưu ý: \"Hành trình Cao cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Người giữ bí mật vui lòng cân nhắc tiêu dùng hợp lý."
  },
  Activity_141509_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
