  Activity_141535_ActivityPlot = {
    Text = "Mùa hè, bãi biển, ánh nắng chói chang, cùng với nhiều gương mặt thân quen.\nDưới ánh sáng đen, hãy quên mọi thứ, chìm đắm trong giấc mơ cuồng hoan thỏa mãn mọi ảo tưởng này đi."
