  },
  Activity_142867_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Ma Nữ Săn Sọ\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Daphodel, trải nghiệm không giới hạn các màn chơi được chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_143933_ActivityName = {
    Text = "Mở khóa miễn phí màn phụ"
