  Activity_144359_ActivityName = {
    Text = "Nhìn Thấu Vạn Tượng"
  },
  Activity_144359_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n1、Sau khi Người giữ bí mật hoàn thành nhiệm vụ hành trình được chỉ định, có thể nhận phần thưởng trong \"Nhìn Thấu Vạn Tượng\".\n2、\"Nhìn Thấu Vạn Tượng\" sẽ kết thúc vào lúc 9:00 ngày 24 tháng 8.\n3、Sau khi mở khóa \"Hành trình Cao cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng bổ sung.\n4、Lưu ý: \"Hành trình Cao cấp\" được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Xin Người giữ bí mật cân nhắc tiêu dùng hợp lý."
  },
