  Activity_145382_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Kình Lạc\" mở, Người giữ bí mật có thể sử dụng đội hình mặc định của hệ thống có chứa Lotan: Ngư Thần, trải nghiệm màn chơi được chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể thức tỉnh trong biên đội.\n<Title:Phần thưởng hoạt động>\n·Sau khi đạt được thử thách màn chơi lần đầu tiên, có thể nhận phần thưởng thử nghiệm trong giao diện hoạt động."
  },
