  Activity_145465_ActivityName = {
    Text = "Nếu mọi thứ vẫn bình thường·klon"
  },
  Activity_145465_ActivityPlot = {
    Text = "Bạn từng mơ ước rằng nếu thảm họa không xảy ra, cuộc sống của mọi người sẽ như thế nào.\nSức mạnh cứu rỗi thế giới của bạn không còn chỗ phát huy, mỗi ngày đều phải vất vả cho cuộc sống học đường bình thường và kiếm được những tín chỉ tệ hại. Không còn hình bóng luyện tập chiến đấu trên sân tập, thay vào đó là hàng loạt lều vải của các hoạt động câu lạc bộ, cùng tiếng hò reo, náo nhiệt; khi tiếng chuông tan học rung lên, những sinh viên đói bụng lập tức tràn vào căng tin... \nKhi gõ cửa nhà những người mà bạn luôn nhớ, bạn sẽ thấy những nụ cười như thế nào?"
  },
  Activity_145465_ActivityStageEndContent = {
    Text = "【Nếu mọi thứ diễn ra như thường】Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Tòa nhà văn phòng hội học sinh\""
