  Activity_146540_ActivityPlot = {
    Text = "Một đoạn ký ức được niêm phong lưu trữ, một đoạn hành trình được ghi vào quá khứ. Khi truy tư, đừng quên dâng lên lễ vật kính ngưỡng."
