  Activity_146541_ActivityName = {
    Text = "Hành Trình Cực Bắc"
  },
  Activity_146541_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1、Sau khi người giữ bí mật hoàn thành nhiệm vụ hành trình được chỉ định, có thể nhận phần thưởng trong \"Hành Trình Cực Bắc\".\n2、\"Hành Trình Cực Bắc\" mở vĩnh viễn.\n3、Sau khi mở khóa \"Hành trình Cao cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4、Lưu ý: \"Hành trình Cao cấp\" được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Mong người giữ bí mật cân nhắc tiêu dùng hợp lý."
