  Activity_148119_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n1、Sau khi người giữ bí mật hoàn thành nhiệm vụ hành trình được chỉ định, có thể nhận phần thưởng trong \"Giờ Ra Về\".\n2、\"Giờ Ra Về\" sẽ kết thúc lúc 9:00 ngày 21 tháng 9.\n3、Sau khi mở khóa \"Hành trình Cao cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4、Lưu ý: \"Hành trình Cao cấp\" được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Mong người giữ bí mật cân nhắc tiêu dùng hợp lý."
  },
  Activity_148119_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
