  Activity_148889_ActivityName = {
    Text = "Khởi nguyên Ogier"
  },
  Activity_148889_ActivityTips = {
    Text = "<Title:Quy tắc sự kiện>\n·Trong thời gian sự kiện \"Bản Nguyên Augir\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Bản Nguyên Augir để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi sự kiện, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng sự kiện>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện sự kiện."
  },
  Activity_15788_ActivityName = {
    Text = "Mỹ Học Giả Kim"
  },
  Activity_15788_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Trong thời gian sự kiện \"Mỹ Học Giả Kim\", sau khi Người Giữ Bí Mật vượt qua \"Tìm Kiếm Kim Quyển\", một phần phần thưởng nguyên liệu sẽ được nhân đôi, mỗi ngày được hưởng 3 lần.\n2, Số lần thưởng nhân đôi chưa sử dụng hết trong ngày sẽ bị xóa vào lúc 9 giờ(GMT+8) ngày hôm sau, Người Giữ Bí Mật nhớ sử dụng kịp thời nhé～"
  },
  Activity_15791_ActivityName = {
    Text = "Linh Tri Bùng Phát"
  },
  Activity_15791_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện \"Linh Tri Bùng Phát\", sau khi Thủ Mật Nhân hoàn thành \"Chế Tễ Tôi Luyện\", một phần phần thưởng nguyên liệu sẽ được nhân đôi, mỗi ngày được hưởng 3 lần.\n2, Số lần thưởng nhân đôi chưa sử dụng hết trong ngày sẽ bị xóa vào 9 giờ sáng ngày hôm sau(GMT+8), Thủ Mật Nhân nhớ sử dụng kịp thời nhé～"
  },
  Activity_15793_ActivityName = {
    Text = "Bóng tối của thị trấn mưa"
  },
  Activity_15793_ActivityPlot = {
    Text = "Mỗi đêm mưa rơi, đều đi kèm với thất ý và cô liêu.\nCó người mất đi tình yêu, có người mất đi tôn nghiêm.\nCòn có người mất đi đầu của chính mình."
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:Điều kiện tham gia>\n·Hoàn thành \"Hành Động Điều Tra\" 2-9·Thường sau đó có thể tham gia.\n<Title:Sự kiện Điều Tra>\n·Trong thời gian hoạt động, mỗi ngày sẽ mở một sự kiện điều tra mới trong \"U Ảnh Vũ Trấn\", Thủ Mật Nhân không cần tiêu hao vật tư để mở khóa và tiến hành điều tra, hoàn thành sự kiện điều tra có thể nhận được Vô Cấu Chi Tâm, Huy Chương Điều Tra và kinh nghiệm Thủ Mật Nhân cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, tiến độ điều tra của \"U Ảnh Vũ Trấn\" sẽ được giữ lại, Thủ Mật Nhân có thể tiêu hao Dung Thực Chi Châu trong Đặc Khiển Kỷ Lục để mở khóa các cuộc điều tra chưa mở khóa, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra giống như trong thời gian hoạt động.<Title:Phần thưởng giới hạn>\n·Trong thời gian hoạt động sẽ mở phần thưởng giới hạn, Thủ Mật Nhân sau khi vượt qua chế độ Thường của \"U Ảnh Vũ Trấn\" và hoàn thành sự kiện điều tra của \"U Ảnh Vũ Trấn\", có thể nhận được phần thưởng Vô Cấu Chi Tâm, Hiền Giả Chi Thạch và Ngân Tâm! Phần thưởng giới hạn chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận thưởng."
  },
