  Activity_20684_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Trong thời gian sự kiện \"Đặc Huấn Cường Hóa\", sau khi Người Giữ Bí Mật vượt qua \"Họng Schwarzschild\", một phần phần thưởng nguyên liệu sẽ được nhân đôi, mỗi ngày được hưởng 3 lần.\n2, Số lần thưởng nhân đôi chưa sử dụng hết trong ngày sẽ bị xóa vào lúc 9 giờ(GMT+8) ngày hôm sau, Người Giữ Bí Mật nhớ sử dụng kịp thời nhé～"
