  Activity_20689_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện \"Thăng Cách Diễn Dịch\", sau khi Thủ Mật Nhân hoàn thành \"Hải Uyên Tàn Tượng\", một phần phần thưởng nguyên liệu sẽ được nhân đôi, mỗi ngày được hưởng 3 lần.\n2, Số lần thưởng nhân đôi chưa sử dụng hết trong ngày sẽ bị xóa vào 9 giờ sáng ngày hôm sau(GMT+8), Thủ Mật Nhân nhớ sử dụng kịp thời nhé～"
