  Activity_20690_ActivityName = {
    Text = "Thăng Cách Diễn Dịch"
  },
  Activity_20690_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện \"Thăng Cách Diễn Dịch\", sau khi Thủ Mật Nhân hoàn thành \"Hỗn Trọc Tàn Tượng\", một phần phần thưởng nguyên liệu sẽ được nhân đôi, mỗi ngày được hưởng 3 lần.\n2, Số lần thưởng nhân đôi chưa sử dụng hết trong ngày sẽ bị xóa vào 9 giờ sáng ngày hôm sau(GMT+8), Thủ Mật Nhân nhớ sử dụng kịp thời nhé～"
  },
  Activity_20691_ActivityName = {
    Text = "Ma Nữ Săn Sọ"
  },
  Activity_20691_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Ma Nữ Săn Sọ\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Daphodel, trải nghiệm không giới hạn các màn chơi được chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_21502_ActivityName = {
    Text = "Sứ Đồ Biển Cả"
  },
  Activity_21502_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Sứ Đồ Biển Cả\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Miriam để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_21781_ActivityName = {
    Text = "Nghiên Tập Tự Chọn"
  },
  Activity_21781_ActivityPlot = {
    Text = "Hoàn thành nhiệm vụ, có thể tự chọn thể thức tỉnh cụ thể trong \"Giới Vực Nghiên Tập\" hoặc Mệnh Luân cụ thể trong \"Luân Chuyển Chi Tướng\"!"
  },
  Activity_21781_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Tích lũy thức tỉnh 50 lần, tích lũy đăng nhập 3 ngày, tích lũy đăng nhập 7 ngày, có thể nhận phần thưởng \"Nguyên Chất Lạc Viên\".\"Nguyên Chất Lạc Viên\" có thể sử dụng trong \"Vật tư: Vật phẩm tiêu hao\", sau khi sử dụng có thể tự chọn 1 thể thức tỉnh cụ thể trong \"Giới Vực Nghiên Tập\"để thức tỉnh.\n2. Tích lũy thức tỉnh 300 lần, tích lũy thức tỉnh 1000 lần, tích lũy đăng nhập 30 ngày, có thể nhận phần thưởng \"Luân Chuyển Chi Thư\".\"Luân Chuyển Chi Thư\" có thể sử dụng trong \"Vật tư: Vật phẩm tiêu hao\", sau khi sử dụng có thể tự chọn 1 Mệnh Luân cụ thể trong \"Luân Chuyển Chi Tướng\"để nhận."
  },
  Activity_22367_ActivityName = {
    Text = "Linh Tri Bùng Phát"
  },
  Activity_22367_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện \"Linh Tri Bùng Phát\", Người Giữ Bí Mật điều tra hoặc tái hiện tại \"Tôi Luyện Chế Tễ\" sẽ nhận thêm 50% phần thưởng(ngoại trừ kinh nghiệm Người Giữ Bí Mật), không giới hạn số lần mỗi ngày."
  },
  Activity_23671_ActivityName = {
    Text = "Lặn Sâu Đối Cờ"
  },
  Activity_23671_ActivityPlot = {
    Text = "Trong thời gian sự kiện, kinh nghiệm Người Giữ Bí Mật mà Người Giữ Bí Mật nhận được thông qua \"Huyễn Mộng Thâm Tiềm\" và\"Tương Vị Đối Dịch\" sẽ được nhân đôi, giới hạn hàng ngày tăng lên 480 điểm."
  },
  Activity_23671_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Trong thời gian sự kiện \"Lặn Sâu Đối Cờ\", kinh nghiệm Người Giữ Bí Mật mà Người Giữ Bí Mật nhận được thông qua \"Huyễn Mộng Thâm Tiềm\" và\"Tương Vị Đối Dịch\" sẽ được nhân đôi, giới hạn hàng ngày tăng lên 480 điểm. Nếu đồng thời mở khóa Khóa Đề Cốt Lõi, kinh nghiệm Người Giữ Bí Mật nhận được qua con đường đó sẽ được nhân đôi rồi nhân đôi thêm lần nữa, giới hạn hàng ngày vẫn giữ nguyên 480 điểm.\n2, Kinh nghiệm nhân đôi Người Giữ Bí Mật chưa sử dụng hết trong ngày sẽ bị xóa vào lúc 9 giờ(GMT+8) ngày hôm sau, Người Giữ Bí Mật nhớ sử dụng hết kịp thời nhé～"
  },
  Activity_23693_ActivityName = {
    Text = "Hậu duệ người da trắng"
  },
  Activity_23693_ActivityPlot = {
    Text = "Tương truyền bên dưới Luân Đế Ni Ân, có một cánh cửa duy nhất.\nNó dẫn đến nơi Chúa Thương Bạch ngự trị…"
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:Điều kiện tham gia>\n·Có thể tham gia sau khi hoàn thành chế độ Thường của Ý Thức Tiềm Du \"Nguyện Vọng Của Kỵ Sĩ\". \n<Title:Sự kiện điều tra>\n·Trong thời gian hoạt động, mỗi ngày sẽ mở một sự kiện điều tra mới trong \"Hậu Duệ Thương Bạch\", Thủ Mật Nhân không cần tiêu hao vật tư để mở khóa tiến hành điều tra, hoàn thành sự kiện điều tra có thể nhận được Vô Cấu Chi Tâm, Huy Hiệu Điều Tra và kinh nghiệm Thủ Mật Nhân cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, tiến độ điều tra của \"Hậu Duệ Thương Bạch\" sẽ được giữ lại, Thủ Mật Nhân có thể tiêu hao Dung Thực Chi Châu trong Ý Thức Tiềm Du để mở khóa các điều tra chưa mở khóa, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra tương tự.<Title:Phần thưởng giới hạn>\n·Trong thời gian hoạt động sẽ có phần thưởng giới hạn, Thủ Mật Nhân vượt qua chế độ Thường của \"Hậu Duệ Thương Bạch\" và hoàn thành sự kiện điều tra của \"Hậu Duệ Thương Bạch\", có thể nhận được Tất Hắc Tỏa Khấu và phần thưởng Ngân Tâm! Phần thưởng giới hạn chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận."
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "Mở khóa sau khi hoàn thành Ý Thức Tiềm Du \"Nguyện Vọng Của Kỵ Sĩ\""
  },
  Activity_23723_ActivityName = {
    Text = "Bão Tố Sắp Đến"
  },
  Activity_23723_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện, Chương 5 Hành Động Điều Tra tạm thời đóng, Chìa Khóa Lệnh \"Vĩnh Thế Chấp Niệm\" tạm thời nhận được khi hoàn thành Chương 4 Hành Động Điều Tra.\n2, Sau khi sự kiện kết thúc, Chương 5 Hành Động Điều Tra sẽ mở lại, Chìa Khóa Lệnh \"Vĩnh Thế Chấp Niệm\" vẫn cần hoàn thành Chương 5 Hành Động Điều Tra để nhận.\n3, Ngoài ra, phần thưởng thành tựu Chương 5, phần thưởng thành tựu màn chơi, phần thưởng khám phá, phần thưởng hoàn thành đã đạt được trước đó sẽ được giữ lại. Khi mở lại(kế hoạch hiện tại là ngày 27 tháng 12), tiến độ đã hoàn thành sẽ được giữ nguyên tối đa, không cần hoàn thành lại."
  },
