    Text = "Suy Diễn Pha Vị"
  },
  Activity_23870_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Trong thời gian sự kiện, hoàn thành nhiệm vụ sự kiện để nhận phần thưởng.\n2, Sau khi sự kiện kết thúc, phần thưởng chưa nhận sẽ không thể nhận lại được, Người Giữ Bí Mật hãy nhớ nhận kịp thời nhé～"
