  },
  Activity_24036_ActivityPlot = {
    Text = "Trong thời gian sự kiện, kinh nghiệm Người Giữ Bí Mật mà Người Giữ Bí Mật nhận được thông qua \"Huyễn Mộng Thâm Tiềm\" và\"Tương Vị Đối Dịch\" sẽ được nhân đôi, giới hạn hàng ngày tăng lên 480 điểm."
  },
  Activity_24036_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Trong thời gian sự kiện \"Lặn Sâu Đối Cờ\", kinh nghiệm Người Giữ Bí Mật mà Người Giữ Bí Mật nhận được thông qua \"Huyễn Mộng Thâm Tiềm\" và\"Tương Vị Đối Dịch\" sẽ được nhân đôi, giới hạn hàng ngày tăng lên 480 điểm. Nếu đồng thời mở khóa Khóa Đề Cốt Lõi, kinh nghiệm Người Giữ Bí Mật nhận được qua con đường đó sẽ được nhân đôi rồi nhân đôi thêm lần nữa, giới hạn hàng ngày vẫn giữ nguyên 480 điểm.\n2, Kinh nghiệm nhân đôi Người Giữ Bí Mật chưa sử dụng hết trong ngày sẽ bị xóa vào lúc 9 giờ(GMT+8) ngày hôm sau, Người Giữ Bí Mật nhớ sử dụng hết kịp thời nhé～"
  },
