  Activity_35844_ActivityName = {
    Text = "Thục nữ biển sâu"
  },
  Activity_35844_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Thục Nữ Biển Sâu\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Murphy để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_35983_ActivityName = {
    Text = "Quà Tặng Học Viện"
  },
  Activity_35983_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật đăng nhập mỗi ngày, có thể nhận phần thưởng điểm danh hàng ngày trong \"Quà Tặng Học Viện\".\n2. Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng điểm danh hàng ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_36841_ActivityName = {
    Text = "Mọi Sự Như Thường"
  },
  Activity_36841_ActivityPlot = {
    Text = "Đây là một ngày đơn giản và vui vẻ của Oreta, đây là mỗi ngày của cô ấy."
  },
  Activity_36841_ActivityTips = {
    Text = "<Title:Điều kiện tham gia>\n·Có thể tham gia sau khi hoàn thành chế độ Thường của Ý Thức Tiềm Du \"Nguyện Vọng Của Kỵ Sĩ\". \n<Title:Sự kiện điều tra>\n·Trong thời gian hoạt động, Thủ Mật Nhân không cần tiêu hao vật tư để mở khóa tiến hành điều tra, hoàn thành sự kiện điều tra có thể nhận được Vô Cấu Chi Tâm, Huy Hiệu Điều Tra và kinh nghiệm Thủ Mật Nhân cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, tiến độ điều tra của \"Mọi Sự Như Thường\" sẽ được giữ lại, Thủ Mật Nhân có thể tiêu hao Dung Thực Chi Châu trong Ý Thức Tiềm Du để mở khóa các điều tra chưa mở khóa, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra tương tự.<Title:Phần thưởng giới hạn>\n·Trong thời gian hoạt động sẽ có phần thưởng giới hạn, Thủ Mật Nhân vượt qua chế độ Thường của \"Mọi Sự Như Thường\" và hoàn thành sự kiện điều tra của \"Mọi Sự Như Thường\", có thể nhận được Tất Hắc Tỏa Khấu và phần thưởng Ngân Tâm! Phần thưởng giới hạn chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận."
  },
  Activity_36841_UnlockConditionExplanation = {
    Text = "Mở khóa sau khi hoàn thành Ý Thức Tiềm Du \"Nguyện Vọng Của Kỵ Sĩ\""
  },
  Activity_36885_ActivityName = {
    Text = "Tiệc Đám Đốt"
  },
  Activity_36886_ActivityName = {
    Text = "Nữ Hoàng Gai"
  },
  Activity_36886_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Nữ Hoàng Gai\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Wanda để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_38716_ActivityName = {
    Text = "Khởi động lại điều tra"
  },
  Activity_38716_ActivityTips = {
    Text = "<Title:Giới thiệu sự kiện>\n·Người giữ bí mật có thể trực tiếp nhận phần thưởng \"Khởi động lại bổ sung\" từ \"Phần thưởng tái nhập học\".\n·Hoàn thành nhiệm vụ huấn luyện để nhận phần thưởng trong hoạt động \"Điều tra khởi động lại\".\n·Hoàn thành tất cả nhiệm vụ huấn luyện, còn có thể nhận thêm phần thưởng."
  },
  Activity_38717_ActivityName = {
    Text = "Báo cáo trở lại trường"
  },
  Activity_38717_ActivityTips = {
    Text = "<Title:Giới thiệu hoạt động>\n·Mỗi ngày, Người Giữ Gìn có thể nhận phần thưởng đăng nhập hàng ngày tại \"Báo cáo trở lại trường\".\n·Phần thưởng sẽ được mở khóa theo số lần đăng nhập tích lũy của Người Giữ Gìn, phần thưởng đăng nhập hàng ngày sẽ được làm mới vào lúc 9 giờ(GMT+8)."
  },
  Activity_38805_ActivityName = {
    Text = "Tiệc Đám Đốt"
  },
  Activity_38805_ActivityPlot = {
    Text = "Isara U, thành phố trong hồ, được cho là quê hương của Vanda. \nLần này, bạn sẽ đi qua cánh cửa giấc mơ, đến với những ngọn tháp cổ xưa với vô số chiếc chuông reo vang…"
  },
  Activity_38805_ActivityTips = {
    Text = "<Title:Tóm tắt hoạt động>\n·Trong thời gian hoạt động, cách chơi \"Tiệc Đám Đốt\" mở cửa trong thời gian giới hạn, và\"duy thức tiềm hành: Tiệc Đám Đốt\" miễn phí mở khóa trong thời gian giới hạn!\n\n<Title:Thành phố trong hồ>\n·\"Thành phố trong hồ\" có 7 màn chơi, mỗi 2 ngày mở 1 màn! Kẻ thù và sự kiện trong mỗi màn có thể xảy ra thay đổi ngẫu nhiên.\n·Xin lưu ý, loại nguyên liệu, số lượng và tỷ lệ pha trộn phần thưởng của mỗi màn có thể xảy ra thay đổi, các màn chơi mở sớm có loại nguyên liệu đơn giản hơn, các màn chơi mở muộn có loại nguyên liệu phong phú hơn nhưng tổng lượng sẽ nhiều hơn, xin hãy chọn phương phápHướng dẫn phù hợp với nhu cầu của bạn!\n·Mỗi màn chơi bao gồm 7 độ khó, phạm vi cấp độ đề xuất là 15~65, tất cả độ khó đều mặc định được mở khóa.\n·Mỗi lần thử thách cần tiêu tốnMenophin×120, độ khó càng cao, phần thưởng nhận được càng nhiều, xin hãy chọn độ khó phù hợp với bản thân để thử thách.\n·Nguyên liệu phần thưởng của màn chơi có thể được đổi lấy nhiều nguyên liệu phát triển thể thức tỉnh tại cửa hàng \"hòm báu kỳ diệu của Wanda\", còn có ảnh đại diện giới hạn hoạt động \"Tên của chìa khóa bạc: Wanda\".\n·Có thể sử dụng trợ chiến hội cựu sinh viên và\"cảm ứng: Lệnh bí mật\"để giúp bạn dễ dàng vượt qua màn chơi hơn..\n\n<Title:Cảm ứng và thành tựu>\n·Tiêu tốn \"Trái tim hưởng lạc\", kích hoạt \"cảm ứng: Lệnh bí mật\", có thể khiến Người Giữ Gìn trở nên mạnh mẽ hơn trong \"Thành phố trong hồ\", thử thách dễ dàng hơn; cũng có thể giúp Người Giữ Gìn nhận thêm tiền hoạt động khi hoàn thành màn chơi.\n·Người giữ bí mật có thể đạt được \"Trái tim hưởng lạc\" bằng cách hoàn thành thành tựu hoạt động, cũng có thể đổi tại cửa hàng \"hòm báu kỳ diệu của Wanda\".\n\n<Title:Duy thức tiềm hành>\n·Trong thời gian hoạt động,\"Tiệc Đám Đốt\" có thể mở khóa miễn phí. Mỗi ngày sẽ giới thiệu một sự kiện điều tra mới trong \"Tiệc Đám Đốt\", hoàn thành sự kiện điều tra có thể nhận được Hạt Nhân Sạch, huy hiệu điều tra và kinh nghiệm của Người Giữ Gìn cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, tiến độ điều tra của \"Tiệc Đám Đốt\" sẽ được giữ lại, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra giống như trong thời gian hoạt động. Nếu trong thời gian hoạt động chưa mở khóa \"Tiệc Đám Đốt\", sau khi hoạt động kết thúc vẫn có thể tiêu tốn \"điểm khởi đầu thực tế\" ×3 để mở khóa.\n·Trong thời gian hoạt động sẽ có phần thưởng thành tựu giới hạn thời gian, Người Giữ Gìn hoàn thành sự kiện điều tra của \"Tiệc Đám Đốt\" sẽ có thể nhận phần thưởng bạc khi hoàn thành thành tựu hoạt động! Phần thưởng thành tựu chỉ được mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận được.\n"
  },
  Activity_41378_ActivityName = {
    Text = "Huấn luyện đặc biệt ứng phó thảm họa"
  },
  Activity_41378_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ được chỉ định, có thể nhận thưởng trong \"Đặc Huấn Nghênh Tai\".\n2,\"Đặc Huấn Nghênh Tai\" mở vĩnh viễn.\n3, Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4, Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Xin Người Giữ Bí Mật cân nhắc chi tiêu hợp lý."
  },
  Activity_43569_ActivityName = {
    Text = "Viễn dương kỷ hành"
  },
  Activity_43569_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành được chỉ định, có thể nhận thưởng trong \"Viễn Dương Kỷ Hành\".\n2.\"Viễn Dương Kỷ Hành\" mở vĩnh viễn.\n3. Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4. Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Người Giữ Bí Mật hãy cân nhắc chi tiêu hợp lý."
  },
  Activity_43570_ActivityName = {
    Text = "Hành trình đến thị trấn tuyết"
  },
  Activity_43570_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành được chỉ định, có thể nhận thưởng trong \"Tuyết Trấn Kỷ Hành\".\n2.\"Tuyết Trấn Kỷ Hành\" mở vĩnh viễn.\n3. Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4. Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Người Giữ Bí Mật hãy cân nhắc chi tiêu hợp lý."
  },
