  Activity_44705_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật đăng nhập mỗi ngày, có thể nhận phần thưởng điểm danh hàng ngày trong \"Quà Tặng Học Viện\".\n2. Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng điểm danh hàng ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_44706_ActivityName = {
    Text = "Giám Mục Nhân Ái"
  },
  Activity_44706_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Giám Mục Nhân Ái\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Salvador để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_44716_ActivityName = {
    Text = "Chúa Tể Trầm Ngủ"
  },
  Activity_44716_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động \"Chúa Tể Trầm Ngủ\" diễn ra, Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Cthulhu, trải nghiệm không giới hạn các màn chơi được chỉ định.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_45664_ActivityName = {
    Text = "Sự Sụp Đổ Của Người Khổng Lồ"
  },
  Activity_45664_ActivityPlot = {
    Text = "Đại dương vô tận, ánh mặt trời thiêu đốt, anh hùng Phi Lợi Sĩ bị lưu đày và tùy tùng duy nhất của anh.\nĐây là một câu chuyện về\"Tìm Kiếm\"."
  },
  Activity_45664_ActivityTips = {
    Text = "<Title:Điều kiện tham gia>\n·Có thể tham gia sau khi hoàn thành chế độ Thường của Ý Thức Tiềm Du \"Nguyện Vọng Của Kỵ Sĩ\". \n<Title:Sự kiện điều tra>\n·Trong thời gian hoạt động, Thủ Mật Nhân không cần tiêu hao vật tư để mở khóa tiến hành điều tra, hoàn thành sự kiện điều tra có thể nhận được Vô Cấu Chi Tâm, Huy Hiệu Điều Tra và kinh nghiệm Thủ Mật Nhân cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, trạng thái mở khóa và tiến độ điều tra của \"Sự Sụp Đổ Của Người Khổng Lồ\" sẽ được giữ lại, hoàn thành các sự kiện điều tra chưa hoàn thành trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra tương tự; nếu chưa mở khóa trong thời gian hoạt động, sau khi hoạt động kết thúc có thể tiêu hao Hiện Thực Khởi Điểm×3 để mở khóa.<Title:Phần thưởng giới hạn>\n·Trong thời gian hoạt động sẽ có phần thưởng giới hạn, Thủ Mật Nhân vượt qua chế độ Thường của \"Sự Sụp Đổ Của Người Khổng Lồ\" và hoàn thành sự kiện điều tra của \"Sự Sụp Đổ Của Người Khổng Lồ\", có thể nhận được Duy Độ Ngưng Tinh và phần thưởng Ngân Tâm! Phần thưởng giới hạn chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận."
  },
  Activity_45664_UnlockConditionExplanation = {
