  Activity_48825_ActivityTips = {
    Text = "<Title:Giới thiệu>\nNếu không có sự dõi theo nhiệt thành của mọi người, Misagar có lẽ sẽ mãi chìm trong đêm dài vô tận. Giờ đây, chúng ta đã thực hiện lời hẹn ước, cùng nhau vượt qua gian khó, chào đón khoảnh khắc kỷ niệm nửa năm. Vì vậy, Mèo Trường sẽ dành tặng bạn một món quà đặc biệt, cảm ơn sự đồng hành của mọi người suốt thời gian qua.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, mỗi Người Giữ Bí Mật có thể chọn 1 trong 8 Thể Đánh Thức SSR giới hạn để đánh thức, bao gồm Turu, Daphdale, Sorel, Lily, Murphy, Wanda, Salvador, \"24\".\n·Khi Người Giữ Bí Mật chọn Thể Đánh Thức đã được đánh thức, sẽ chuyển đổi thành Mảnh vỡ Thể Đánh Thức tương ứng ×1 và Kết Tủa Nguồn Gốc ×50; nếu cấp Khai Linh của Thể Đánh Thức tương ứng đã đạt tối đa, sẽ chuyển đổi thành \"Mảnh Linh Hạch\" × 1 và \"Kết Tủa Nguồn Gốc\" × 150."
  },
  Activity_48825_BannerText = {
    Text = "Nhận miễn phí Thể Đánh Thức giới hạn"
  },
  Activity_48826_ActivityName = {
    Text = "Hoàng hôn và Bình minh"
  },
  Activity_48826_ActivityPlot = {
    Text = "Đăng nhập mỗi ngày để nhận Vòng Mệnh SSR kỷ niệm giới hạn \"Đêm Cực và Bình Minh\", tổng cộng có thể nhận 16 cái!"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:Giới thiệu>\nĐây là một bài thơ dành tặng người chơi, về lý tưởng, về niềm tin, về khoảng thời gian cùng nhau tiến bước. Nguyện trái tim chân thành không bao giờ ngừng đập, nguyện Chìa Khóa Bạc dẫn lối tiến về phía trước.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, sau khi đăng nhập mỗi ngày, Người Giữ Bí Mật có thể nhận Vòng Mệnh SSR kỷ niệm giới hạn \"Đêm Cực và Bình Minh\" tại \"Đêm Cực và Bình Minh\", tổng cộng có thể nhận 16 lần.\n·Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng đăng nhập trong ngày sẽ làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_48826_BannerText = {
    Text = "Nhận miễn phí Mệnh Luân SSR giới hạn"
  },
  Activity_48827_ActivityName = {
    Text = "Ngân Tâm trong chiếc mũ"
  },
  Activity_48827_ActivityPlot = {
    Text = "Theo thống kê chưa đầy đủ, trong nửa năm qua, chiếc mũ của Mèo Trường đã bị học sinh vỗ hàng ngàn lần, nhiều Ngân Tâm nhỏ bé không đáng chú ý đã rơi xuống đất nhưng không ai quan tâm. Nhân viên vệ sinh của trường rất phiền lòng, hiện trường đã thu gom những Ngân Tâm này, rửa sạch hoàn toàn và lưu giữ tại quầy nhận đồ thất lạc, xin mời chủ nhân tự đến nhận lại kịp thời."
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:Giới thiệu>\nTheo thống kê chưa đầy đủ, trong nửa năm qua, chiếc mũ của Mèo Trường đã bị học sinh vỗ hàng ngàn lần, nhiều Ngân Tâm nhỏ bé không đáng chú ý đã rơi xuống đất nhưng không ai quan tâm. Nhân viên vệ sinh của trường rất phiền lòng, hiện trường đã thu gom những Ngân Tâm này, rửa sạch hoàn toàn và lưu giữ tại quầy nhận đồ thất lạc, xin mời chủ nhân tự đến nhận lại.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, sau khi đăng nhập mỗi ngày, Người Giữ Bí Mật có thể nhận \"Ngân Tâm\" ×1000 tại \"Ngân Tâm trong chiếc mũ\", tối đa có thể nhận 5 lần.\n·Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng đăng nhập trong ngày sẽ làm mới lúc 9 giờ(GMT+8)."
  },
