  },
  Activity_51905_ActivityName = {
    Text = "Quà Tặng Học Viện"
  },
  Activity_51905_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật đăng nhập mỗi ngày, có thể nhận phần thưởng điểm danh hàng ngày trong \"Quà Tặng Học Viện\".\n2. Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng điểm danh hàng ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_52040_ActivityName = {
    Text = "Lễ tế thẳm sâu"
  },
  Activity_52040_ActivityPlot = {
    Text = "Phản chiếu trên biển sâu, giấc mơ của vua tan biến, vương quốc của thần đã thối rữa. \nNàng từ những ảo mộng cũ kỹ bước tới, đi vào đống đổ nát của tương lai sụp đổ. \nNàng hỏi hố sâu, hố sâu im lặng không lời. \nNàng dâng lễ tế cho hố sâu, đáp lại nàng, chỉ có chính bản thân nàng."
  },
  Activity_52040_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Tiếng vọng từ vực thẳm\""
  },
  Activity_52040_ActivityTips = {
    Text = "<Title: Hoạt động giới thiệu>\n1,Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ sự kiện thông qua các chế độ chơi giới hạn thời gian 「Sự xuất hiện của Thần Quốc」, 「Lệnh của vua」 và 「Phần thưởng thành tựu」. Tiền tệ sự kiện có thể được sử dụng trong 「Phản hồi của vực thẳm」 để hiến tế và nhận các phần thưởng vật phẩm, bao gồm SR mệnh vòng giới hạn sự kiện 「Gọi của Biển Sâu」, đá triết học, Hạt Nhân Sạch Will, Lõi Lưu Minh, v.v.\n2,Trong thời gian hoạt động, 「Thế giới Mộng Ảo: Xâm phạm」 sẽ mở miễn phí.\n\n<Title: Thời gian hoạt động>\n1,Từ 9:00 ngày 17 tháng 6 - 9:00 ngày 1 tháng 7 (GMT+8), tất cả nội dung hoạt động đều có thể tham gia.\n2,Từ 9:00 ngày 1 tháng 7 - 9:00 ngày 8 tháng 7 (GMT+8), chỉ còn lại 「Phản hồi của vực thẳm」 và 「Phần thưởng thành tựu」, các nội dung khác đều đã kết thúc và không thể tham gia.\n\n<Title: Sự xuất hiện của Thần Quốc>\n1,「Sự xuất hiện của Thần Quốc」 gồm có 5 màn chơi, mỗi 2 ngày sẽ tự động mở 1 màn.\n2,Mỗi lần thách đấu sẽ tiêu hao 「Menophin」× 120, khi thách đấu thành công sẽ nhận được tiền tệ sự kiện 「nước mắt của người thờ cúng」, 「Máu của người thờ cúng」 và 「tủy của người tế lễ」. Khi thách đấu với chế độ nhân đôi, cần tiêu hao 240 Menophin, phần thưởng nhiệm vụ màn chơi cũng sẽ được nhân đôi, nhưng tỷ lệ đồng điều không thay đổi.\n3,Khi hoàn thành 100% 「Phần thưởng thành tựu」, chức năng 「tái hiện」 của màn chơi đã hoàn thành sẽ được mở khóa. Mỗi lần 「tái hiện」 tiêu hao 「Menophin」× 120. Lưu ý: Khi sử dụng chức năng 「tái hiện」 sẽ không thể nhận được tỷ lệ đồng điều.\n4,Người chơi có thể sử dụng hỗ trợ Hội bạn đồng học và 「cảm ứng: Lễ tế Hải Vực」 để giúp hoàn thành màn chơi dễ dàng hơn.\n\n<Title: Bonus Tế Phẩm>\n1,Người giữ bí mật sở hữu các Thể thức tỉnh hoặc mệnh vòng cụ thể (không cần phải ra trận) có thể làm cho phần thưởng nhiệm vụ màn chơi 「Sự xuất hiện của Thần Quốc」 của 「nước mắt của người thờ cúng」, 「Máu của người thờ cúng」 và 「tủy của người tế lễ」 nhận được phần thưởng rơi đặc biệt (bao gồm cả tái hiện), chi tiết phần thưởng như sau:\n·Thể thức tỉnh 「Miriam」: khởi linh 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·SSR mệnh vòng 「sức mạnh thành tâm」: Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·SR mệnh vòng 「Gọi của Biển Sâu」: Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n2,Bonus của các Thể thức tỉnh hoặc mệnh vòng khác nhau sẽ được tính cộng gộp.\n\n<Title: cảm ứng: Lễ tế Hải Vực>\n1,Người giữ bí mật có thể nhận 「Trái tim thành kính」 thông qua hoàn thành các thành tựu hoạt động.\n2,Tiêu hao 「Trái tim thành kính」 để kích hoạt 「cảm ứng: Lễ tế Hải Vực」, có thể nhận được các phần thưởng sau: \n(1) Giúp Người Giữ Gìn trở nên mạnh hơn trong chế độ chơi hoạt động 「Sự xuất hiện của Thần Quốc」, để việc thách đấu trở nên dễ dàng hơn.\n(2) Tăng tiền tệ sự kiện nhận được sau khi hoàn thành thách đấu 「Sự xuất hiện của Thần Quốc」.\n(3) Kích hoạt chế độ chơi hoạt động 「Lệnh của vua」.\n\n<Title: Lệnh của vua>\n·Kích hoạt cảm ứng 「Thử thách hy sinh」, sẽ tự động nhận được 60 「nước mắt của người thờ cúng」 mỗi giờ, tích trữ tối đa 25 giờ.\n\n<Title: Phản hồi của vực thẳm>\n1,「Phản hồi của vực thẳm」 gồm có ba bàn thờ, thời gian mở như sau:\n·「Altar của Nước Mắt Tinh Khiết」: 9 giờ ngày 17 tháng 6 mở.\n·「Bàn thờ máu khỉ」: 9 giờ ngày 19 tháng 6 mở.\n·「Bàn thờ Tinh hồn」: 9 giờ ngày 21 tháng 6 mở.\n2,Mỗi lần hiến tế lễ vật sẽ tiêu hao 500 「nước mắt của người thờ cúng」/「Máu của người thờ cúng」/「tủy của người tế lễ」 và ngẫu nhiên nhận được năm phần thưởng vật phẩm từ bàn thờ.\n3,Phần thưởng vật phẩm của mỗi bàn thờ được chia thành hai loại 「quà tặng của Thần Quốc」 và 「phần thưởng bình thường」. Khi reset có thể làm số lượng còn lại của phần thưởng chỉ định reset về tối đa, cụ thể quy tắc như sau:\n(1) Hai lần reset đầu tiên: Khi 「quà tặng của Thần Quốc」 không còn lại, Người Giữ Gìn có thể chọn reset, sau khi reset sẽ làm 「quà tặng của Thần Quốc」 và 「phần thưởng bình thường」 số lượng còn lại được reset về tối đa; hoặc có thể chọn tiếp tục hiến tế lễ vật, khi 「phần thưởng bình thường」 cũng không còn lại, phải reset để tiếp tục hiến tế lễ vật.\n(2) Từ lần reset thứ 3 trở đi: Khi 「phần thưởng bình thường」 không còn lại mới có thể reset, reset sẽ làm 「phần thưởng bình thường」 số lượng còn lại reset về tối đa, 「quà tặng của Thần Quốc」 không reset nữa.\n\n<Title: Thế giới Mộng Ảo>\n1,「Thế giới Mộng Ảo」 là kiểu điều tra mới, so với hình thức diễn dịch cốt truyện thông thường, 「Thế giới Mộng Ảo」 tập trung nhiều hơn vào biểu hiện chữ viết, lượng nội dung chữ cũng nhiều hơn.\n2,Trong 「Thế giới Mộng Ảo: Xâm phạm」, bạn sẽ thông qua liên kết tinh thần với Miriam, trực tiếp đọc ký ức của cô ấy, từ đó chứng kiến: Miriam khi còn là một đứa trẻ từng bước trải qua đau khổ tại Lemuria, bối rối trong tín ngưỡng, vùng vẫy trong tín ngưỡng, cuối cùng bước lên con đường trở thành cả Đấng Cứu Thế và Kẻ hủy diệt…\n3,Trong thời gian hoạt động, 「Thế giới Mộng Ảo: Xâm phạm」 sẽ miễn phí mở. Cứ mỗi 2 ngày sẽ có sự kiện mới ra mắt, sau khi hoàn thành 「Thế giới Mộng Ảo: Xâm phạm」, có thể nhận phần thưởng tại Phần thưởng thành tựu như bạc tâm, SR mệnh vòng giới hạn sự kiện 「Gọi của Biển Sâu」, v.v.; phần thưởng thành tựu chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận.\n4,Sau khi hoạt động kết thúc, tiến độ điều tra của 「Thế giới Mộng Ảo: Xâm phạm」 sẽ được giữ lại, nếu trong thời gian hoạt động chưa mở khóa 「Thế giới Mộng Ảo: Xâm phạm」, sau khi hoạt động kết thúc vẫn có thể tiêu hao 「điểm khởi đầu thực tế」×7 để mở khóa.\n5,Dù có đang trong thời gian hoạt động hay không, sau khi hoàn thành 「Thế giới Mộng Ảo: Xâm phạm」 đều có thể nhận được 「Mật lệnh: Lễ hội Biển」.\n\n\n\n"
  },
