  Activity_53829_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Lễ kỷ niệm Vàng Đỏ\""
  },
  Activity_53829_ActivityTips = {
    Text = "<Title:Tổng quan hoạt động>\n1,Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ hoạt động 「Quá khứ Hoa Hồng」 và 「Phần thưởng thành tựu」 thông qua các hình thức chơi có thời hạn, 「Quạt Lông Chim Thông Linh」 có thể đổi lấy phần thưởng phong phú trong 「Lễ hội Vàng Đỏ」, bao gồm vòng mệnh SR giới hạn hoạt động 「Triệu ánh nhìn yêu thương」,「Hạt Nhân Sạch Will」,「Lõi Lưu Minh」,「Phân mảnh đá hiền」,「Tinh thể mịn」v.v.\n2,Trong thời gian hoạt động, hoàn thành nhiệm vụ của 「Phần thưởng thành tựu」 có thể nhận được ảnh đại diện giới hạn hoạt động 「Tên của chìa khóa bạc: Sorrel」,vòng mệnh SR giới hạn hoạt động 「Triệu ánh nhìn yêu thương」,bạc tâm và số lượng lớn tiền tệ hoạt động 「Quạt Lông Chim Thông Linh」.\n3,Trong thời gian hoạt động, 「Bản ghi đặc nhiệm: Lời ca ngợi hoa hồng」 sẽ mở miễn phí.\n\n<Title:Thời gian hoạt động>\n1,Từ 9:00 ngày 1 tháng 7 đến 9:00 ngày 15 tháng 7 (GMT+8), tất cả nội dung hoạt động đều có thể tham gia.\n2,Từ 9:00 ngày 15 tháng 7 đến 9:00 ngày 22 tháng 7 (GMT+8), chỉ giữ lại 「Lễ hội Vàng Đỏ」 và 「Phần thưởng thành tựu」,các nội dung khác đã kết thúc không thể tham gia.\n\n<Title:Quá khứ Hoa Hồng>\n1,「Quá khứ Hoa Hồng」bao gồm 9 màn chơi, mỗi ngày tự động mở 1 màn.\n2,Mỗi lần thách thức sẽ tiêu tốn 「Menophin」× 120, thách thức các màn chơi khác nhau ngoài việc nhận được các vật liệu rơi khác nhau, còn nhận được tiền tệ hoạt động 「Quạt Lông Chim Thông Linh」.\n3,Màn chơi hoạt động lần này là màn chơi vật liệu chiến đấu trực tiếp, sau khi hoàn thành có thể tái hiện! Mỗi lần 「tái hiện」 tiêu tốn 「Menophin」× 120.\n4,Xin lưu ý: Khi sử dụng chức năng 「tái hiện」, không thể nhận được tỷ lệ đồng điều.\n\n<Title:Thưởng thêm từ quạt>\n1,Người giữ bí mật sở hữu thể thức tỉnh hoặc vòng mệnh cụ thể (không yêu cầu xuất trận) có thể làm cho tiền thưởng từ nhiệm vụ màn chơi 「Quá khứ Hoa Hồng」 trong 「Quạt Lông Chim Thông Linh」 nhận được phần thưởng rơi thêm (bao gồm tái hiện), cụ thể phần thưởng thêm như sau:\n·Thể thức tỉnh 「Sorrel」: Khởi linh 0/1/2/3 trở lên, thưởng thêm 20%/30%/40%/50%\n·Vòng mệnh SSR 「Nhân danh đóa hồng」: Vị trí chồng 0/1/2/3 trở lên, thưởng thêm 20%/30%/40%/50%\n·Vòng mệnh SR 「Triệu ánh nhìn yêu thương」: Vị trí chồng 0/1/2/3 trở lên, thưởng thêm 20%/30%/40%/50%\n2,Khác nhau giữa các thể thức tỉnh hoặc vòng mệnh sẽ được tính theo cách cộng dồn cho phần thưởng 「quạt thưởng thêm」.\n\n<Title:Bản ghi đặc nhiệm>\n1,Trong thời gian hoạt động, những Người Giữ Gìn đã mở khóa trước 「Bản ghi đặc nhiệm: Lời ca ngợi hoa hồng」, mở khóa lại sẽ nhận được 「Quạt Lông Chim Thông Linh」×600 bồi thường.\n2,Trong 「Bản ghi đặc nhiệm: Lời ca ngợi hoa hồng」, Người Giữ Gìn sẽ sử dụng một đội hình đặc biệt bao gồm cốt truyện được định trước 「Sorrel」 để thách thức."
  },
  Activity_53829_BannerText = {
    Text = "Sự kiện chơi game mở cửa trong thời gian giới hạn!"
  },
  Activity_54375_ActivityName = {
    Text = "Lời ca ngợi hoa hồng"
  },
  Activity_54375_ActivityPlot = {
    Text = "Các quý bà, quý ông.\nĐêm hiền hòa đã mở màn, hãy chuẩn bị rượu ngon bên cạnh.\nĐây là một câu chuyện dài, xin hãy lắng nghe chúng tôi kể từ từ…"
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:Điều kiện tham gia>\n·Hoàn thành \"điều tra hành động\" 2-9·Thông thường sau khi có thể tham gia.\n<Title:Sự kiện điều tra>\n·Trong thời gian hoạt động, mỗi ngày sẽ ra mắt một sự kiện điều tra mới trong \"Lời khen Hoa hồng\", Người Giữ Gìn không cần tiêu thụ vật tư để mở khóa và tiến hành điều tra, hoàn thành sự kiện điều tra sau có thể nhận được Hạt Nhân Sạch Will, huy hiệu điều tra và kinh nghiệm của Người Giữ Gìn cùng các phần thưởng điều tra khác.\n·Sau khi hoạt động kết thúc, tiến độ điều tra của \"Lời khen Hoa hồng\" sẽ được bảo lưu, Người Giữ Gìn có thể sử dụng hạt ngọc tan rã trong bản ghi đặc biệt để mở khóa điều tra chưa hoàn thành, sau khi hoàn thành các sự kiện điều tra chưa xong trong thời gian hoạt động cũng có thể nhận được phần thưởng điều tra giống như trong thời gian diễn ra sự kiện.<Title:Phần thưởng có hạn>\n·Trong thời gian hoạt động sẽ xuất hiện phần thưởng có giới hạn, Người Giữ Gìn hoàn thành chế độ thông thường của \"Lời khen Hoa hồng\" và sự kiện điều tra \"Lời khen Hoa hồng\" sau đó có thể nhận được Hạt Nhân Sạch Will, đá triết học và bạc tâm làm phần thưởng! Phần thưởng có giới hạn chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành hoặc nhận."
  },
  Activity_54402_ActivityName = {
    Text = "Bệnh Nhân Phân Liệt·Hỗn Loạn"
  },
  Activity_54402_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Bệnh Nhân Phân Liệt·Hỗn Loạn\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm \"24\"để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
