  Activity_56429_ActivityPlot = {
    Text = "Cô ấy luôn đi trước mọi người. \n Một bước, hai bước, dấu chân của cô ấy dẫn dắt bước chân của mọi người. \n Nhưng mọi người thường dễ quên rằng, ranh giới giữa thiên tài và kẻ điên chỉ mỏng như một sợi tóc."
  },
  Activity_56429_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Lời dạy của thầy\""
  },
  Activity_56429_ActivityTips = {
    Text = "<Title:Tổng quan hoạt động>\nTrong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ sự kiện \"Phụ kiện búp bê\" thông qua các chế độ chơi giới hạn thời gian \"Cánh cửa hư vô\" và \"Phần thưởng thành tựu\", \"Phụ kiện búp bê\" có thể đổi lấy phần thưởng trong \"Dạy dỗ của thầy cô\", bao gồm vòng mệnh SR giới hạn sự kiện \"Cây gậy của người chăn cừu\", Lõi Lưu Minh, Hạt Nhân Sạch Will, Phân mảnh đá hiền, Tinh thể mịn, v. v.\n\n<Title:Cánh cửa hư vô>\n1,\"Cánh cửa hư vô\" bao gồm 9 màn chơi nguyên liệu không cần khám phá mà chỉ chiến đấu, mỗi ngày mở 1 màn.\n2, Mỗi lần thách đấu sẽ tiêu tốn \"Menophin\" × 120, thành công trong thách đấu sẽ nhận được nguyên liệu nuôi dưỡng và tiền tệ sự kiện.\n3, Sau khi hoàn thành màn chơi, sẽ mở khóa chức năng \"tái hiện\" của màn chơi đó. Xin lưu ý: khi sử dụng chức năng \"tái hiện\", không thể nhận tỷ lệ đồng điều.\n4, Có thể sử dụng sự hỗ trợ của hội cựu sinh viên để giúp bạn dễ dàng hoàn thành màn chơi hơn.\n\n<Title:Phụ kiện búp bê tăng cường>\n1, Người giữ bí mật sở hữu thể thức tỉnh hoặc vòng mệnh cụ thể(không yêu cầu tham gia) sẽ làm cho phần thưởng nhiệm vụ trong màn chơi \"Cánh cửa hư vô\" nhận được thêm phần rơi \"Phụ kiện búp bê\"(bao gồm tái hiện), cụ thể như sau:\n·Thể thức tỉnh \"Tan chảy · Đóa\": khởi linh 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%\n·Vòng mệnh SSR \"Ma-nơ-canh của miền quên lãng\": vị trí chồng 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%\n·Vòng mệnh SR \"Cây gậy của người chăn cừu\": vị trí chồng 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%\n2, Các thể thức tỉnh hoặc vòng mệnh khác nhau có \"tăng cường phụ kiện búp bê\" sẽ được tính theo cách cộng dồn.\n3, Đặc biệt, phần thưởng thách đấu lần đầu độ khó điên cuồng sẽ không bị ảnh hưởng bởi các tăng cường trên.\n\n<Title:Dạy dỗ của thầy cô>\n1, Mỗi lần \"Đổi phụ kiện\" sẽ tiêu tốn 750 \"Phụ kiện búp bê\", ngẫu nhiên nhận 5 phần thưởng trong \"Dạy dỗ của thầy cô\".\n2, Phần thưởng vật phẩm trong \"Dạy dỗ của thầy cô\"được chia thành 2 loại: \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\", khi thiết lập lại có thể làm cho số lượng còn lại của phần thưởng vật phẩm đặc biệt được thiết lập lại về giới hạn, quy tắc cụ thể như sau:\n(1)5 lần thiết lập đầu tiên: khi không còn số lượng \"Đặc biệt vật phẩm\", Người Giữ Gìn có thể chọn thiết lập lại, sau khi thiết lập lại sẽ đưa số lượng còn lại của \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\" về giới hạn; cũng có thể chọn tiếp tục đổi, khi không còn số lượng \"Vật phẩm bình thường\", phải thực hiện thiết lập lại để tiếp tục đổi.\n(2)Thiết lập lại từ lần thứ 6 trở đi: khi không còn số lượng \"Vật phẩm bình thường\" mới có thể thực hiện thiết lập lại, thiết lập lại sẽ đưa số lượng còn lại của \"Vật phẩm bình thường\" về giới hạn, \"Đặc biệt vật phẩm\" sẽ không còn được thiết lập lại nữa.\n\n<Title:Thời gian hoạt động>\n1, Từ 9:00 ngày 17 tháng 2 đến 9:00 ngày 3 tháng 3(GMT+8), tất cả nội dung trong tổng quan hoạt động đều có thể tham gia.\n2, Từ 9:00 ngày 3 tháng 3 đến 9:00 ngày 10 tháng 3(GMT+8), chỉ giữ lại \"Dạy dỗ của thầy cô\" và \"Phần thưởng thành tựu\", các nội dung khác đều đã kết thúc không thể tham gia.\n3, Sau 9:00 ngày 10 tháng 3(GMT+8), số lượng \"Phụ kiện búp bê\" còn lại chưa được đổi sẽ được thu hồi theo tỷ lệ mỗi cái đổi lấy \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn chú ý kiểm tra email."
  },
