  Activity_61156_ActivityName = {
    Text = "Hành trình cuối cùng"
  },
  Activity_61156_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành được chỉ định, có thể nhận thưởng trong \"Chung Yên Kỷ Hành\".\n2.\"Chung Yên Kỷ Hành\" mở vĩnh viễn.\n3. Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4. Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Người Giữ Bí Mật hãy cân nhắc chi tiêu hợp lý."
  },
  Activity_61369_ActivityName = {
    Text = "Tiệm Tiến Nhạc Luật"
  },
  Activity_61369_ActivityPlot = {
    Text = "Người Giữ Bí Mật có thể chọn một trong các Vòng Mệnh giới hạn sau để đánh thức!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:Giới thiệu>\nHắc Trì biến ảo khôn lường, Mệnh Luân xoay chuyển tuần hoàn, dưới sự dẫn dắt của âm nhạc Hamelin, vô hạn nhạc luật cùng tấu, hội tụ thành Mệnh Luân của hành trình mà bạn đã vượt qua. Nguyện sự trợ lực của chúng đồng hành cùng bạn đến tận dấu lặng của bản tấu minh cuối cùng.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động chỉ cần đăng nhập một ngày, là có thể tự chọn một trong 12 Mệnh Luân giới hạn sau đây để thức tỉnh, bao gồm:\"Thánh Ca Của Thần Vương\",\"Bộ Sưu Tập Quý Giá Nhất\",\"Nhân Danh Tường Vi\",\"Vượt Qua Đau Đớn\",\"Sự Khai Sinh Bí Ẩn\",\"Giới Luật Của Nữ Vương\",\"Thần Ngôn Thạch Bản\",\"Dị Thể Phản Phệ\",\"Uy Lực Của Sự Thành Kính\",\"Cuối Câu Thơ Tiên\",\"Sự Nuôi Dưỡng Từ Bi\",\"Thời Khắc May Mắn\"."
  },
  Activity_61369_BannerText = {
    Text = "Nhận miễn phí Vòng Mệnh giới hạn"
  },
  Activity_61370_ActivityName = {
    Text = "Trái tim bạc"
  },
  Activity_61370_ActivityPlot = {
    Text = "Đăng nhập hàng ngày có thể nhận Mệnh Luân SSR kỷ niệm giới hạn \"Tâm Thuần Ngân\", tổng cộng có thể nhận 16 cái！"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:Giới thiệu>\nDù thế giới có sụp đổ ra sao, chỉ cần mỗi người đều gìn giữ trái tim thuần ngân trong trẻo thuở ban đầu, câu chuyện rồi sẽ tuần hoàn, sinh mệnh mới sẽ tái sinh trên mảnh đất hoang tàn.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, Thủ Mật Nhân mỗi ngày sau khi đăng nhập có thể nhận Mệnh Luân SSR kỷ niệm giới hạn \"Sơ Tâm Thuần Ngân\" trong \"Sơ Tâm Thuần Ngân\", tổng cộng có thể nhận 16 lần.\n·Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Thủ Mật Nhân, phần thưởng đăng nhập trong ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_61370_BannerText = {
    Text = "Nhận miễn phí Mệnh Luân SSR giới hạn"
  },
  Activity_61371_ActivityName = {
    Text = "Nguyện Ước Sáu Cánh Nở Rộ"
  },
  Activity_61371_ActivityPlot = {
    Text = "Giữa cơn biến động của Hắc Trì, Ngân Tâm đến từ vô hạn chiều không gian đã rơi rải qua khe nứt chiều không gian bên bờ Hắc Trì. Tháp Vi cẩn thận thu gom chúng lại, đặt vào một góc Hắc Trì. Dẫu những Ngân Tâm này không thể ngăn chặn sự lan rộng của Dung Thực, nhưng nỗi nhớ và tâm ý ẩn chứa bên trong mãi mãi tỏa sáng rực rỡ."
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:Giới thiệu>\nGiữa cơn biến động của Hắc Trì, Ngân Tâm đến từ vô hạn chiều không gian đã rơi rải qua khe nứt chiều không gian bên bờ Hắc Trì. Tháp Vi cẩn thận thu gom chúng lại, đặt vào một góc Hắc Trì. Dẫu những Ngân Tâm này không thể ngăn chặn sự lan rộng của Dung Thực, nhưng nỗi nhớ và tâm ý ẩn chứa bên trong mãi mãi tỏa sáng rực rỡ.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, Thủ Mật Nhân mỗi ngày sau khi đăng nhập có thể nhận \"Ngân Tâm\" × 1000 trong hoạt động, tối đa có thể nhận 6 lần.\n·Trong thời gian hoạt động, Thủ Mật Nhân đăng nhập tích lũy ngày thứ 7, còn có thể trực tiếp nhận thể thức tỉnh giới hạn kỳ hiện tại \"Tháp Vi\"！\n·Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Thủ Mật Nhân, phần thưởng đăng nhập trong ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_61371_BannerText = {
    Text = "Điểm danh nhận thật nhiều Ngân Tâm"
  },
