  Activity_65387_ActivityName = {
    Text = "Lời Xin Lỗi Của Mèo Trường"
  },
  Activity_65387_ActivityPlot = {
    Text = "Gần đây do lỗ hổng trong biện pháp phòng hộ của nhà trường, dẫn đến tình trạng Dung Thực <Del:「Văn bản tạm thời, chấm đỏ」> xâm nhập khuôn viên trường ngày càng nhiều, gây ra nhiều bất tiện cho các học sinh. Vì vậy, phòng giáo vụ đã đặc biệt thiết lập nhiều điểm tiếp tế, phát vật tư cho các bạn học sinh như một khoản bồi thường.(Xét trách nhiệm do sai sót quản lý cơ sở vật chất, vật tư tiếp tế lần này hoàn toàn do mèo trường chịu trách nhiệm vận chuyển.)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:Giới thiệu>\nGần đây do lỗ hổng trong biện pháp phòng hộ của nhà trường, dẫn đến tình trạng Dung Thực <Del:「Văn bản tạm thời, chấm đỏ」> xâm nhập khuôn viên trường ngày càng nhiều, gây ra nhiều bất tiện cho các học sinh. Vì vậy, phòng giáo vụ đã đặc biệt thiết lập nhiều điểm tiếp tế, phát vật tư cho các bạn học sinh như một khoản bồi thường.(Xét trách nhiệm do sai sót quản lý cơ sở vật chất, vật tư tiếp tế lần này hoàn toàn do mèo trường chịu trách nhiệm vận chuyển.)\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động, Thủ Mật Nhân mỗi ngày sau khi đăng nhập có thể nhận「Ngân Tâm」× 500 trong「Lời Xin Lỗi Của Mèo Trường」, tối đa có thể nhận 5 lần.\n·Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Thủ Mật Nhân, phần thưởng đăng nhập trong ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
  },
  Activity_65387_BannerText = {
    Text = "Điểm danh nhận Ngân Tâm"
  },
  Activity_65502_ActivityName = {
    Text = "Tiệm Tiến Nhạc Luật·Song Tấu"
  },
  Activity_65502_ActivityPlot = {
    Text = "Người Giữ Bí Mật có thể chọn một trong các Vòng Mệnh giới hạn sau để đánh thức!"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:Giới thiệu>\nHắc Trì biến ảo khôn lường, Mệnh Luân xoay chuyển tuần hoàn, dưới sự dẫn dắt của âm nhạc Hamelin, vô hạn nhạc luật cùng tấu, hội tụ thành Mệnh Luân của hành trình mà bạn đã vượt qua. Nguyện sự trợ lực của chúng đồng hành cùng bạn đến tận dấu lặng của bản tấu minh cuối cùng.\n\n<Title:Quy tắc hoạt động>\n·Trong thời gian hoạt động chỉ cần đăng nhập một ngày, là có thể tự chọn một trong 12 Mệnh Luân giới hạn sau đây để thức tỉnh, bao gồm:\"Thánh Ca Của Thần Vương\",\"Bộ Sưu Tập Quý Giá Nhất\",\"Nhân Danh Tường Vi\",\"Vượt Qua Đau Đớn\",\"Sự Khai Sinh Bí Ẩn\",\"Giới Luật Của Nữ Vương\",\"Thần Ngôn Thạch Bản\",\"Dị Thể Phản Phệ\",\"Uy Lực Của Sự Thành Kính\",\"Cuối Câu Thơ Tiên\",\"Sự Nuôi Dưỡng Từ Bi\",\"Thời Khắc May Mắn\"."
  },
  Activity_65502_BannerText = {
    Text = "Nhận miễn phí Vòng Mệnh giới hạn"
  },
  Activity_65521_ActivityName = {
    Text = "Hộp Quà Tiếp Tế Điều Tra"
  },
  Activity_65521_ActivityPlot = {
    Text = "Vật tư tiếp tế điều tra do Phòng Giáo vụ Mythage cung cấp. Được Alistair tinh chế từ các vật thể trôi nổi trong Hắc Trì."
  },
  Activity_65949_ActivityName = {
    Text = "Quà Tặng Học Viện"
  },
  Activity_65949_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1. Sau khi Người Giữ Bí Mật đăng nhập mỗi ngày, có thể nhận phần thưởng điểm danh hàng ngày trong \"Quà Tặng Học Viện\".\n2. Phần thưởng sẽ được mở khóa lần lượt theo số ngày đăng nhập tích lũy của Người Giữ Bí Mật, phần thưởng điểm danh hàng ngày sẽ được làm mới lúc 9 giờ(GMT+8)."
