  },
  Activity_66375_ActivityTips = {
    Text = "<Title: Chung Chiến Nguyên Sơ>\n·\"Chung Chiến Nguyên Sơ\" bao gồm 7 cấp độ không thể tái hiện, thử thách trực tiếp Nguyên Thủy Chi Thị, ngày đầu mở 3 cấp độ đầu tiên, sau đó cứ mỗi 3 ngày mở thêm 1 cấp độ.\n·Mỗi lần chiến thắng khiêu chiến Nguyên Thủy Chi Thị tương ứng, bạn sẽ nhận được phần thưởng tương ứng.\n·Mỗi loại Nguyên Thủy Chi Thị đều có số lượng phân thân lớn, mỗi khi một loại Nguyên Thủy Chi Thị bị bất kỳ Người Giữ Bí Mật nào khiêu chiến thành công, số lượng \"tàn dư thế giới\" của loại Nguyên Thủy Chi Thị này sẽ giảm đi 1. Khi tất cả các phân thân của loại Nguyên Thủy Chi Thị bị tiêu diệt, cấp độ tương ứng sẽ đóng lại và không thể khiêu chiến lại.\n·Tất cả các cấp độ đều chịu ảnh hưởng của \"Dòng Lũ Đen Tối·Cuối Cùng\", nhưng mỗi cấp độ sẽ cung cấp các tạo vật khác nhau như \"lõi bạc tinh khiết\", mang lại cho bạn sức mạnh tăng cường đáng kể. Ngoài ra, mỗi cấp độ còn cung cấp tạo vật \"Toàn Tri Nhãn\", giúp Tà Vy nhận được 120 điểm điên cuồng khi bắt đầu trận chiến, đồng thời tăng cường 50% sát thương, lá chắn và hiệu ứng hồi sức sống mà cô ấy gây ra.\n·Tất cả các cấp độ phải chọn trợ chiến, trong toàn bộ hoạt động, mỗi Người Giữ Bí Mật đã quan tâm lẫn nhau chỉ có thể hỗ trợ bạn một lần. Do sử dụng trợ chiến, phần thưởng tỷ lệ đồng điều thực tế sẽ tăng thêm 50% dựa trên mức thưởng cơ bản.\n·Người Giữ Bí Mật cần hoàn thành ít nhất Hành Động Điều Tra 2-9 để tham gia hoạt động này.\n\n<Title: Điều Tra Hành Động: Chương Cuối>\n·Vẫn cần tự mình đánh bại các Nguyên Thủy Chi Thị chính trong Hành Động Điều Tra 9-5 đến 9-11. Những cấp độ đặc biệt này không có thành tựu, không có sao, cũng không có sự hỗ trợ từ tạo vật \"Toàn Tri Nhãn\", không thể sử dụng trợ chiến, và khó khăn hơn.\n·Sau khi sự kiện \"Chung Chiến Nguyên Sơ\" kết thúc, các cấp độ tiếp theo của \"Điều Tra Hành Động: Chương Cuối\" sẽ được mở khóa. Khi cùng với những Người Giữ Bí Mật khác tiêu diệt tất cả các phân thân của mọi Nguyên Thủy Chi Thị, có thể mở khóa trước các cấp độ tương ứng trong Hành Động Điều Tra 9-5 đến 9-11."
  },
  Activity_66375_BannerText = {
    Text = "Sự kiện đặc biệt đã bắt đầu!"
  },
  Activity_66908_ActivityName = {
    Text = "Hơi Thở Phong Nhưỡng"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Hơi Thở Phong Nhưỡng\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm Teyis để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Giác Tỉnh Thể trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_67077_ActivityName = {
    Text = "Hồi Tưởng Hành Trình Hiến Lễ IX"
  },
  Activity_67077_ActivityPlot = {
    Text = "Một đoạn ký ức được niêm phong lưu trữ, một đoạn hành trình được ghi vào quá khứ. Khi truy tư, đừng quên dâng lên lễ vật kính ngưỡng."
  },
  Activity_67718_ActivityName = {
    Text = "Trước khi mùa xuân phai nhạt·tái hiện"
  },
  Activity_67718_ActivityPlot = {
    Text = "Tiếng cười của các cô gái vang lên, vọng lại trong khu vườn chưa bị ngọn lửa bao trùm. \nHãy tạm dừng để hòa mình vào vẻ đẹp của những ký ức xưa, bạn của tôi. \nNghe mùa xuân chưa phai tàn, thì thầm kể về những câu chuyện của quá khứ."
  },
  Activity_67718_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Nhà kính của Colette\""
  },
  Activity_67718_ActivityTips = {
    Text = "<Title:Giới thiệu hoạt động>\n1, Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập ba loại \"thơ văn\" thông qua gameplay giới hạn thời gian \"Khu vườn ký ức\", \"Nụ hôn của Myu-s\" và \"Phần Thưởng Thành Tựu\". \"Thơ văn\" có thể dùng để trao đổi lấy vật phẩm thưởng trong \"Nhà hoa của Colette\", bao gồm vòng mệnh SR giới hạn hoạt động \"Hoa và thơ của ngày hôm qua\", \"Hạt Nhân Sạch Will\", \"Lõi Lưu Minh\", \"Phân mảnh đá hiền\", \"Tinh thể mịn\", v. v.\n2, Trong thời gian hoạt động, \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\" sẽ được mở miễn phí.\n\n<Title:Thời gian hoạt động>\n1,9:00 ngày 10 tháng 8 - 9:00 ngày 7 tháng 9(GMT+8), tất cả nội dung hoạt động đều có thể tham gia.\n2,9:00 ngày 7 tháng 9 - 9:00 ngày 14 tháng 9(GMT+8), chỉ giữ lại \"Nhà hoa của Colette\" và \"Phần Thưởng Thành Tựu\", các nội dung khác đã kết thúc và không thể tham gia.\n\n<Title: Khu vườn ký ức>\n1,\"Khu vườn ký ức\" bao gồm 5 màn chơi, mỗi 2 ngày tự động mở 1 màn.\n2, Mỗi lần thử thách sẽ tiêu tốn Menophin × 120, thử thách thành công sẽ nhận được tiền tệ hoạt động \"thơ văn u uất\", \"Thơ của tiếc nuối\" và \"Thơ vui vẻ\".\n3, Sau khi hoàn thành màn chơi, mở khóa chức năng \"Tái hiện\" của màn đó. Lưu ý: Khi sử dụng chức năng \"Tái hiện\", không thể nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng hỗ trợ chiến đấu của hội cựu sinh viên và \"cảm ứng: Elegi Vườn\"để giúp bạn hoàn thành dễ dàng hơn.\n5, Ngày thứ 2 sau khi màn chơi được mở khóa, mở khóa độ khó điên cuồng của màn đó. Hoàn thành lần đầu độ khó điên cuồng có thể nhận được phần thưởng tiền tệ hoạt động phong phú.\n6, Lưu ý: Thử thách độ khó điên cuồng không tiêu tốn Menophin, không thể tái hiện, và sau lần đầu hoàn thành, thử thách lặp lại sẽ không nhận được thêm phần thưởng tiền tệ hoạt động.\n\n<Title: Tăng thêm thơ văn>\n1, Người giữ bí mật sở hữu Thể thức tỉnh hoặc vòng mệnh cụ thể(không yêu cầu đưa vào trận) có thể giúp \"thơ văn u uất\", \"Thơ của tiếc nuối\" và \"Thơ vui vẻ\" trong phần thưởng nhiệm vụ màn chơi \"Khu vườn ký ức\" nhận được tăng thêm rơi đồ(bao gồm tái hiện), chi tiết như sau:\n·Thể thức tỉnh \"Ôrla\": khởi linh 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·Vòng mệnh SSR \"Hồi kết của bài thơ\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·Vòng mệnh SR \"Hoa và thơ của ngày hôm qua\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n2,\"Tăng thêm thơ văn\" của các Thể thức tỉnh hoặc vòng mệnh khác nhau được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thử thách lần đầu hoàn thành độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"Tăng thêm thơ văn\".\n\n<Title:cảm ứng: Elegi Vườn>\n1, Người giữ bí mật có thể nhận \"Trái tim tro tàn\" thông qua việc hoàn thành thành tựu hoạt động.\n2, Tiêu tốn \"Trái tim tro tàn\", kích hoạt \"cảm ứng: Elegi Vườn\", có thể nhận được các tăng thêm sau:\n(1)Giúp Người Giữ Gìn trở nên mạnh hơn trong gameplay hoạt động \"Khu vườn ký ức\", thử thách dễ dàng hơn.\n(2)Tăng tiền tệ hoạt động nhận được sau khi hoàn thành thử thách \"Khu vườn ký ức\".\n(3)Kích hoạt gameplay hoạt động \"Nụ hôn của Myu-s\".\n\n<Title: Nụ hôn của Myu-s>\n·Sau khi kích hoạt cảm ứng \"Vạn vật sinh trưởng\", mỗi giờ tự động nhận được \"thơ văn u uất\" × 60, tối đa lưu trữ 25 giờ.\n·Sau khi kích hoạt cảm ứng \"Trao đổi thơ lấy hoa\", \"Nụ hôn của Myu-s\" mỗi giờ có thể nhận thêm \"Thơ của tiếc nuối\" × 60.\n\n<Title: Nhà hoa của Colette>\n1,\"Nhà hoa của Colette\" có tổng cộng ba vườn hoa, thời gian mở như sau:\n·\"Vườn hoa diên vĩ\": Mở lúc 9 giờ ngày 10 tháng 8.\n·\"Vườn hoa cát cánh\": Mở lúc 9 giờ ngày 12 tháng 8.\n·\"Vườn Hoa hồng\": Mở lúc 9 giờ ngày 14 tháng 8.\n2, Mỗi lần trao đổi sẽ tiêu tốn \"thơ văn u uất\"/\"Thơ của tiếc nuối\"/\"Thơ vui vẻ\" × 750, ngẫu nhiên nhận được năm vật phẩm thưởng trong vườn hoa.\n3, Vật phẩm thưởng của mỗi vườn hoa được chia thành \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\", khi đặt lại có thể khôi phục số lượng Còn Lại của vật phẩm đặc biệt về giới hạn trên, quy tắc cụ thể như sau:\n(1)2 lần đặt lại đầu tiên: Khi \"Đặc biệt vật phẩm\" không Còn Lại, Người Giữ Gìn có thể chọn đặt lại, sau khi đặt lại sẽ khôi phục số lượng Còn Lại của \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\" về giới hạn trên; cũng có thể chọn tiếp tục trao đổi, khi \"Vật phẩm bình thường\" cũng không Còn Lại, phải đặt lại mới có thể tiếp tục trao đổi.\n(2)Từ lần đặt lại thứ 3 trở đi: Chỉ khi \"Vật phẩm bình thường\" không Còn Lại mới có thể đặt lại, việc đặt lại sẽ khôi phục số lượng Còn Lại của \"Vật phẩm bình thường\" về giới hạn trên, \"Đặc biệt vật phẩm\" sẽ không được đặt lại nữa.\n4, Sau 9:00 ngày 14 tháng 9(GMT+8), \"thơ văn\" chưa được trao đổi Còn Lại sẽ được thu hồi theo tỷ lệ mỗi đơn vị đổi \"Vé hoa hồng vàng\" × 40, Người Giữ Gìn vui lòng chú ý kiểm tra hộp thư.\n\n<Title: Bản ghi đặc nhiệm>\n1, Trong thời gian hoạt động, \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\" sẽ được mở miễn phí. Cứ mỗi 2 ngày sẽ có sự kiện mới, sau khi hoàn thành \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\" có thể nhận được bạc tâm, vòng mệnh SR giới hạn hoạt động \"Hoa và thơ của ngày hôm qua\" và các phần thưởng khác trong phần thưởng thành tựu. Phần thưởng thành tựu chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận.\n2, Sau khi hoạt động kết thúc, tiến độ điều tra của \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\" sẽ được giữ lại. Nếu chưa mở khóa \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\" trong thời gian hoạt động, sau khi hoạt động kết thúc vẫn có thể tiêu tốn \"điểm khởi đầu thực tế\" ×7 để mở khóa.\n3, Dù có trong thời gian hoạt động hay không, sau khi hoàn thành \"Bản ghi đặc nhiệm: Nơi ở của hoa hồng\"đều có thể nhận được \"Mật lệnh: Bài thơ dâng mùa xuân\"."
  },
