  Activity_67745_ActivityPlot = {
    Text = "Elworth luôn phủ đầy băng tuyết, giống như lòng căm hận của cô ấy. \nKhi tương lai và quá khứ chạm tay vào nhau, chiến binh sẽ giương cao thanh kiếm, lao tới trả thù số phận. \nKhi cô ấy đối mặt với những con sóng đen, bạn chính là biểu tượng dẫn lối của cô ấy."
  },
  Activity_67745_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Hàm Núi Khổng Lồ\""
  },
  Activity_67745_ActivityTips = {
    Text = "<Title:Giới thiệu hoạt động>\n1, Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập ba loại \"Bông hoa\" thông qua gameplay giới hạn thời gian \"Sự tham vọng của thú vật\" và \"Phần thưởng thành tựu\", \"Bông hoa\" có thể dùng để đổi tại \"Miệng Núi Khổng Lồ\"để nhận phần thưởng đạo cụ, bao gồm vòng mệnh SR giới hạn hoạt động \"Cho đến khi tuyết tan\", \"Hạt Nhân Sạch Will\", \"Lõi Lưu Minh\", \"Phân mảnh đá hiền\", \"Tinh thể mịn\", v. v.\n2, Trong thời gian hoạt động, \"Bản ghi đặc nhiệm: Người trở về của Elworth\" sẽ được mở miễn phí.\n\n<Title:Thời gian hoạt động>\n1, Từ 9:00 ngày 13 tháng 7 đến 9:00 ngày 10 tháng 8(GMT+8), tất cả nội dung hoạt động đều có thể tham gia.\n2, Từ 9:00 ngày 10 tháng 8 đến 9:00 ngày 17 tháng 8(GMT+8), chỉ giữ lại \"Miệng Núi Khổng Lồ\" và \"Phần thưởng thành tựu\", các nội dung khác đã kết thúc và không thể tham gia.\n\n<Title: Sự tham vọng của thú vật>\n1,\"Sự tham vọng của thú vật\" bao gồm 5 màn chơi, cứ mỗi 2 ngày sẽ tự động mở 1 màn.\n2, Mỗi lần thử thách sẽ tiêu thụ \"Menophin\" × 120, thử thách thành công sẽ nhận được tiền tệ hoạt động \"Bông hoa đóng băng\", \"Búp hoa sương bạc\" và \"Bông hướng dương non\".\n3, Sau khi hoàn thành màn chơi, mở khóa chức năng \"Tái hiện\" của màn đó. Xin lưu ý: Khi sử dụng chức năng \"Tái hiện\", không thể nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng Trợ Chiến Hội Cựu Sinh Viên và \"cảm ứng: Nuốt chửng sơn mạch\"để giúp bạn hoàn thành dễ dàng hơn.\n5, Xin lưu ý: Thử thách độ khó điên cuồng không tiêu thụ Menophin, không thể tái hiện, và sau lần đầu hoàn thành, thử thách lặp lại sẽ không nhận được thêm phần thưởng tiền tệ hoạt động.\n\n<Title: Tăng thêm Bông hoa>\n1, Người giữ bí mật sở hữu Thể thức tỉnh hoặc vòng mệnh cụ thể(không yêu cầu đưa vào trận) có thể giúp \"Bông hoa đóng băng\", \"Búp hoa sương bạc\" và \"Bông hướng dương non\" trong phần thưởng nhiệm vụ màn chơi \"Sự tham vọng của thú vật\" nhận được tăng thêm tỷ lệ rơi đồ(bao gồm tái hiện), chi tiết tăng thêm như sau:\n·Thể thức tỉnh \"Máu Liên · Shiro\": khởi linh 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·Vòng mệnh SSR \"Chìm trong màu đỏ thẫm\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n·Vòng mệnh SR \"Cho đến khi tuyết tan\": Vị trí chồng 0/1/2/3 trở lên, tăng thêm 20%/30%/40%/50%\n2,\"Tăng thêm Bông hoa\" của các Thể thức tỉnh hoặc vòng mệnh khác nhau được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thử thách lần đầu hoàn thành độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"Tăng thêm Bông hoa\".\n\n<Title:cảm ứng: Nuốt chửng sơn mạch>\n1, Người giữ bí mật có thể nhận được \"Trái Tim Tiêu Thụ\" bằng cách hoàn thành thành tựu hoạt động. \n2, Tiêu thụ \"Trái Tim Tiêu Thụ\", kích hoạt \"cảm ứng: Nuốt chửng sơn mạch\", có thể giúp Người Giữ Gìn trở nên mạnh hơn trong gameplay hoạt động \"Sự tham vọng của thú vật\", thử thách dễ dàng hơn.\n\n<Title: Miệng Núi Khổng Lồ>\n1,\"Miệng Núi Khổng Lồ\" có tổng cộng ba cửa hàng đổi thưởng, thời gian mở như sau:\n·\"Tham vọng nuốt chửng\": Mở lúc 9 giờ ngày 13 tháng 7.\n·\"Ý chí báo thù\": Mở lúc 9 giờ ngày 15 tháng 7.\n·\"Hy vọng tái sinh\": Mở lúc 9 giờ ngày 17 tháng 7.\n2, Mỗi lần đổi sẽ tiêu thụ \"Bông hoa đóng băng\"/\"Búp hoa sương bạc\"/\"Bông hướng dương non\" × 750, ngẫu nhiên nhận được năm phần thưởng vật phẩm trong cửa hàng đổi thưởng.\n3, Phần thưởng vật phẩm của mỗi cửa hàng đổi thưởng được chia thành hai loại \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\", khi làm mới có thể đặt lại số lượng còn lại của phần thưởng đặc biệt về giới hạn tối đa, quy tắc cụ thể như sau:\n(1) 2 lần làm mới đầu tiên: Khi \"Đặc biệt vật phẩm\" không còn số lượng, Người Giữ Gìn có thể chọn làm mới, sau khi làm mới sẽ đặt lại số lượng còn lại của \"Đặc biệt vật phẩm\" và \"Vật phẩm bình thường\" về giới hạn tối đa; cũng có thể chọn tiếp tục đổi, khi \"Vật phẩm bình thường\" cũng không còn số lượng, phải làm mới mới có thể tiếp tục đổi.\n(2) Bắt đầu từ lần làm mới thứ 3: Chỉ có thể làm mới khi \"Vật phẩm bình thường\" không còn số lượng, làm mới sẽ đặt lại số lượng còn lại của \"Vật phẩm bình thường\" về giới hạn tối đa, \"Đặc biệt vật phẩm\" sẽ không được làm mới nữa.\n4, Sau 9:00 ngày 17 tháng 8(GMT+8), các \"Bông hoa\" còn lại chưa đổi sẽ được thu hồi theo tỷ lệ mỗi cái đổi \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn chú ý kiểm tra hộp thư.\n\n<Title: Bản ghi đặc nhiệm>\n1, Trong thời gian hoạt động, \"Bản ghi đặc nhiệm: Người trở về của Elworth\" sẽ được mở miễn phí. Sau khi hoàn thành \"Bản ghi đặc nhiệm: Người trở về của Elworth\" có thể nhận được \"bạc tâm\", vòng mệnh SR giới hạn hoạt động \"Cho đến khi tuyết tan\" và các phần thưởng khác trong Phần thưởng thành tựu, Phần thưởng thành tựu chỉ mở trong thời gian hoạt động, sau khi hoạt động kết thúc sẽ không thể hoàn thành và nhận.\n2, Sau khi hoạt động kết thúc, tiến độ điều tra của \"Bản ghi đặc nhiệm: Người trở về của Elworth\" sẽ được giữ lại, nếu chưa mở khóa \"Bản ghi đặc nhiệm: Người trở về của Elworth\" trong thời gian hoạt động, sau khi hoạt động kết thúc vẫn có thể tiêu thụ \"điểm khởi đầu thực tế\" × 7 để mở khóa.\n3, Dù có hay không trong thời gian hoạt động, sau khi hoàn thành \"Bản ghi đặc nhiệm: Người trở về của Elworth\"đều có thể nhận được \"Mật lệnh: Sự giác ngộ của những ngọn núi\"."
  },
  Activity_67745_BannerText = {
    Text = "Sự kiện chơi game mở cửa trong thời gian giới hạn!"
  },
  Activity_67746_ActivityName = {
    Text = "Cánh cửa Vạn Tượng · Phiên bản tái hiện"
  },
  Activity_67746_ActivityPlot = {
    Text = "Không ai biết được những năm tháng cô ấy im lặng trước cánh cửa. \nCô ấy vốn không có ý định tham gia vào bất kỳ thế giới cụ thể nào, không nên để bất kỳ dòng thời gian liên tục nào chi phối tinh thần, không cho phép bất kỳ thứ gì xao động sự ổn định của cánh cửa tận cùng. \nCho đến khoảnh khắc ánh mắt cô ấy gặp ánh mắt của bạn."
  },
  Activity_67746_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"tiếng vang\""
  },
  Activity_67746_ActivityTips = {
    Text = "<Title:Tổng quan hoạt động>\n1, Trong thời gian hoạt động, Người Giữ Gìn có thể thu thập tiền tệ sự kiện \"Poin Akhir\" thông qua các chế độ chơi giới hạn thời gian \"Kiểm tra cuối cùng\" và\"Phần thưởng thành tựu\".\"Poin Akhir\" có thể được đổi lấy phần thưởng hấp dẫn trong \"Tiếng vọng\", bao gồm bánh xe số phận SR giới hạn sự kiện \"Cánh cửa Sự thật\",\"Hạt Nhân Sạch Will\",\"Lõi Lưu Minh\",\"Phân mảnh đá hiền\",\"Tinh thể mịn\" v. v.\n2, Trong thời gian sự kiện, hoàn thành nhiệm vụ\"Phần thưởng thành tựu\" có thể nhận được hình đại diện giới hạn sự kiện \"Tên của chìa khóa bạc: Tà Vy\", bánh xe số phận SR giới hạn sự kiện \"Cánh cửa Sự thật\", bạc tâm và số lượng lớn tiền tệ sự kiện \"Poin Akhir\".\n\n<Title:Thời gian sự kiện>\n1, Từ 9:00 ngày 3 tháng 11 đến 9:00 ngày 17 tháng 11(GMT+8), tất cả nội dung sự kiện đều có thể tham gia.\n2, Từ 9:00 ngày 17 tháng 11 đến 9:00 ngày 24 tháng 11(GMT+8), chỉ giữ lại \"Tiếng vọng\" và\"Phần thưởng thành tựu\", các nội dung khác đã kết thúc không thể tham gia.\n\n<Title: Kiểm tra cuối cùng>\n1,\"Kiểm tra cuối cùng\" bao gồm 9 màn chơi, mỗi ngày tự động mở 1 màn.\n2, Mỗi lần thử thách sẽ tiêu tốn \"Menophin\" × 120, thử thách các màn chơi khác nhau sẽ nhận được các vật liệu rơi khác nhau, ngoài ra còn nhận được tiền tệ sự kiện \"Poin Akhir\".\n3, Các màn chơi sự kiện lần này là màn chơi vật liệu chiến đấu trực tiếp, sau khi hoàn thành có thể tái hiện! Mỗi lần \"tái hiện\" tiêu tốn \"Menophin\" × 120.\n4, Xin lưu ý: Khi sử dụng chức năng \"tái hiện\", sẽ không nhận được tỷ lệ đồng điều.\n\n<Title:Thêm vào Poin Akhir>\n1, Người giữ bí mật sở hữu thể thức tỉnh hoặc bánh xe số phận cụ thể(không yêu cầu có mặt) có thể khiến \"Poin Akhir\" trong phần thưởng nhiệm vụ màn chơi \"Kiểm tra cuối cùng\" nhận được thêm vật phẩm rơi(bao gồm tái hiện), cụ thể như sau:\n·Thể thức tỉnh \"Tà Vy\": Khởi linh 0/1/2/3 trở lên, thêm 20%/30%/40%/50%\n·Bánh xe số phận SSR \"Vòng quay vô định\": Vị trí chồng 0/1/2/3 trở lên, thêm 20%/30%/40%/50%\n·Bánh xe số phận SR \"Cánh cửa Sự thật\": Vị trí chồng 0/1/2/3 trở lên, thêm 20%/30%/40%/50%\n2, Các \"thêm vào Poin Akhir\" của các thể thức tỉnh hoặc bánh xe số phận khác nhau sẽ được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thử thách đầu tiên độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"thêm vào Poin Akhir\".\n\n<Title:Tiếng vọng>\n1,\"Tiếng vọng\" chỉ mở cửa trong khoảng thời gian từ 9:00 ngày 3 tháng 11 đến 9:00 ngày 24 tháng 11(GMT+8).\n2, Sau 9:00 ngày 24 tháng 11(GMT+8), số\"Poin Akhir\" chưa được đổi sẽ được thu hồi theo tỷ lệ mỗi \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn chú ý kiểm tra email."
  },
