  Activity_68349_ActivityTips = {
    Text = "<Title: Vượt Qua Tinh Thần·Mua Trước Giới Hạn>\n·Sự kiện mua trước giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Vượt Qua Tinh Thần·Mua Trước Giới Hạn\" mới có thể nhận.\n·Sau khi mua \"Vượt Qua Tinh Thần·Mua Trước Giới Hạn\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·\"Vượt Qua Tinh Thần·Mua Trước Giới Hạn\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua."
