  Activity_68406_ActivityName = {
    Text = "Chôn sâu trong ký ức"
  },
  Activity_68406_ActivityPlot = {
    Text = "Mọi người chôn sâu những điều khát khao trong tâm trí, đeo mặt nạ ảo tưởng để làm vừa lòng thế giới.\nNghe này, tiếng kêu của những thứ bị che đậy bởi xác thịt đang vang vọng trong sương mù ký ức.\nHãy trống rỗng tâm trí, bỏ qua xác thịt, để chào đón bản thân thật sự."
  },
  Activity_68406_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện nay chỉ có thể tham gia \"Phòng khám thần kinh\""
  },
  Activity_68406_ActivityTips = {
    Text = "<Title:Tổng quan sự kiện>\nTrong thời gian sự kiện, Người Giữ Gìn có thể thu thập tiền tệ sự kiện thông qua các chế độ chơi giới hạn thời gian \"Chữa lành nỗi sợ hãi\" và\"Phần thưởng thành tựu\", tiền tệ sự kiện có thể được sử dụng để đổi lấy phần thưởng vật phẩm tại \"Phòng khám thần kinh\", bao gồm vòng mệnh SR giới hạn sự kiện \"Con lắc thôi miên\",đá triết học, Hạt Nhân Sạch Will, Lõi Lưu Minh, v. v.\n\n<Title:Thời gian sự kiện>\n1, Từ 9:00 ngày 7 tháng 4 đến 9:00 ngày 21 tháng 4(GMT+8), tất cả nội dung sự kiện đều có thể tham gia.\n2, Từ 9:00 ngày 21 tháng 4 đến 9:00 ngày 28 tháng 4(GMT+8), chỉ giữ lại \"Phòng khám thần kinh\" và\"Phần thưởng thành tựu\", các nội dung khác đều đã kết thúc và không thể tham gia.\n\n<Title:Chữa lành nỗi sợ hãi>\n1,\"Chữa lành nỗi sợ hãi\" bao gồm 5 màn chơi, mỗi 2 ngày tự động mở 1 màn.\n2, Mỗi lần thách thức sẽ tiêu tốn \"Menophin\" × 120, thách thức thành công sẽ nhận được tiền tệ sự kiện.\n3, Sau khi hoàn thành màn chơi, mở khóa chức năng \"tái hiện\" của màn chơi đó. Xin lưu ý: Khi sử dụng chức năng \"tái hiện\", không thể nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng sự giúp đỡ từ hội cựu sinh viên để giúp bạn dễ dàng hoàn thành màn chơi hơn.\n\n<Title:Tăng cường sự kiện>\n1, Người giữ bí mật sở hữu thể thức tỉnh hoặc vòng mệnh cụ thể(không yêu cầu có mặt) có thể khiến phần thưởng nhiệm vụ trong \"Chữa lành nỗi sợ hãi\" bao gồm \"Báo cáo chẩn đoán\" nhận được thêm phần thưởng rơi ngẫu nhiên(bao gồm tái hiện), cụ thể như sau:\n·Thể thức tỉnh \"Clementine\": Khởi linh 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n·Vòng mệnh SSR \"Nỗi đau ẩn dấu\": Vị trí chồng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n·Vòng mệnh SR \"Con lắc thôi miên\": Vị trí chồng 0/1/2/3 trở lên, tăng 20%/30%/40%/50%\n2, Các \"Tăng cường sự kiện\" của thể thức tỉnh hoặc vòng mệnh khác nhau sẽ được tính theo cách cộng dồn.\n3,Đặc biệt, phần thưởng thách thức lần đầu độ khó điên cuồng sẽ không bị ảnh hưởng bởi \"Tăng cường sự kiện\".\n\n<Title:Phòng khám thần kinh>\n1, Mỗi lần \"Gửi báo cáo\" sẽ tiêu tốn 1000 \"Báo cáo chẩn đoán\", ngẫu nhiên nhận được 5 phần thưởng vật phẩm trong \"Phòng khám thần kinh\".\n2, Phần thưởng vật phẩm trong \"Phòng khám thần kinh\"được chia thành 2 loại:\"Đặc biệt vật phẩm\" và\"Vật phẩm bình thường\", khi đặt lại có thể khiến số lượng còn lại của vật phẩm đặc biệt được đặt lại về giới hạn tối đa, quy tắc cụ thể như sau:\n(1)5 lần đặt lại đầu tiên: Khi \"Đặc biệt vật phẩm\" không còn số lượng, Người Giữ Gìn có thể chọn đặt lại, sau khi đặt lại sẽ đưa số lượng còn lại của \"Đặc biệt vật phẩm\" và\"Vật phẩm bình thường\" về giới hạn tối đa; cũng có thể chọn tiếp tục đổi, khi \"Vật phẩm bình thường\" cũng không còn số lượng, phải thực hiện đặt lại mới có thể tiếp tục đổi.\n(2)Đặt lại từ lần thứ 6 trở đi: Khi \"Vật phẩm bình thường\" không còn số lượng mới có thể thực hiện đặt lại, đặt lại sẽ đưa số lượng còn lại của \"Vật phẩm bình thường\" về giới hạn tối đa,\"Đặc biệt vật phẩm\" sẽ không còn đặt lại.\n3, Sau 9:00 ngày 28 tháng 4(GMT+8), số lượng \"Báo cáo chẩn đoán\" chưa đổi còn lại sẽ được thu hồi theo tỷ lệ mỗi lần đổi \"Vé hoa hồng vàng\" × 40, xin Người Giữ Gìn chú ý kiểm tra email."
