  Activity_70438_ActivityPlot = {
    Text = "Lễ hội Cầu Tuế sắp đến, mọi người đều tập trung vào việc chuẩn bị lễ kỷ niệm, không ai để ý đến mảng đen ở góc đang từ từ di chuyển, tên tù nhân nhỏ bé biến thành chất lỏng thoát khỏi nhà tù. \n Khi vết nứt chiều không gian lấp lánh, khối lông đen bắt đầu phân chia... một biển mèo đen đang tiêu thụ cả trường học! \n Bạn vốn muốn làm ngơ, giao những sự kiện kỳ lạ này cho phòng quản lý trường giải quyết. \n Nhưng vì chúng có thể rớt bạc tâm và vé vàng, bạn đã thay đổi ý định."
  },
  Activity_70438_ActivityTips = {
    Text = "<Title:Tổng quan sự kiện>\nSự kiện chơi game \"Ussar mèo mèo\" mở cửa trong thời gian giới hạn! Trong thời gian sự kiện, Người Giữ Gìn có thể đánh bại \"Nhóm mèo nhảy múa hỗn loạn\" và nhận được nhiều bạc tâm và vé hoa hồng vàng!\n\n<Title:Thời gian sự kiện>\nTừ 9:00 ngày 24 tháng 1 đến 9:00 ngày 5 tháng 2(GMT+8), trong thời gian sự kiện, mỗi ngày đều có thể tham gia vào các màn chơi \"Nhóm mèo nhảy múa hỗn loạn\" mở khóa trong ngày, nội dung của các màn chơi đã kết thúc không thể tham gia lại.\n\n<Title:Nhóm mèo nhảy múa hỗn loạn>\n1,\"Nhóm mèo nhảy múa hỗn loạn\" có tổng cộng 12 màn chơi, mỗi ngày mở khóa các màn chơi khác nhau, nội dung của các màn chơi đã kết thúc không thể tham gia lại.\n2, Mỗi lần thách thức không tiêu tốn \"Menophin\", sau khi hoàn thành 1 màn chơi có thể nhận được \"Hạt Nhân Sạch Will\",\"bạc tâm\",\"vé hoa hồng vàng\".\n3, Màn chơi này không thể sử dụng sự trợ giúp của hội cựu sinh viên.\n4, Trong màn chơi trong ngày, mỗi thể thức tỉnh chỉ được ra trận 1 lần.\n5, Mỗi ngày của màn chơi đều cần dùng các cõi chỉ định để thách thức.\n·Ngày 24 tháng 1: Cõi hỗn mang\n·Ngày 25 tháng 1: Cõi hải vực\n·Ngày 26 tháng 1: Cõi thịt máu\n·Ngày 27 tháng 1: Cõi siêu chiều\n·Ngày 28 tháng 1: Không giới hạn\n·Ngày 29 tháng 1: Không giới hạn\n·Ngày 30 tháng 1: Cõi hỗn mang và cõi hải vực\n·Ngày 31 tháng 1: Cõi thịt máu và cõi siêu chiều\n·Ngày 1 tháng 2: Cõi hỗn mang và cõi thịt máu\n·Ngày 2 tháng 2: Cõi hải vực và cõi siêu chiều\n·Ngày 3 tháng 2: Cõi hỗn mang và cõi siêu chiều\n·Ngày 4 tháng 2: Cõi thịt máu và cõi hải vực"
  },
