  Activity_71098_ActivityPlot = {
    Text = "Cô ấy luôn đi trước mọi người. \n Một bước, hai bước, dấu chân của cô ấy dẫn dắt bước chân của mọi người. \n Nhưng mọi người thường dễ quên rằng, ranh giới giữa thiên tài và kẻ điên chỉ mỏng như một sợi tóc."
