  Activity_71100_ActivityName = {
    Text = "Phục hồi Thần Vương"
  },
  Activity_71100_ActivityPlot = {
    Text = "Trong lời cầu nguyện khao khát vô tận, Ngài ngắn ngủi hồi tỉnh từ giấc ngủ dài dằng dặc, dành cho thế giới nhàm chán này một ánh nhìn chân thực. \nTrong sức sống vĩnh hằng, ánh nhìn ấy thật quá đỗi ngắn ngủi."
  },
  Activity_71100_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện tại chỉ có thể tham gia \"Biển sâu Giác tri\""
  },
  Activity_71100_ActivityTips = {
    Text = "<Title:Giới thiệu sự kiện>\n1, Trong thời gian sự kiện, Người Giữ Bí Mật có thể thu thập tiền tệ sự kiện \"Tự Tư Mệt Mỏi\",\"Tự Tư Bi Sầu\",\"Tự Tư Hoan Duyệt\" thông qua lối chơi giới hạn \"Ngưng Thị Thâm Hải\" và\"Phần Thưởng Thành Tựu\". Tiền tệ sự kiện có thể dùng để mua hàng hóa tại \"Giác Tri Hải Uyên\", bao gồm Mệnh Luân SR giới hạn sự kiện \"Ngai Đá Xanh\", Lõi Lưu Minh, Lõi Vô Cấu, Mảnh Hiền Thạch, Nghê Thái Ngưng Tinh, v. v.\n2, Trong thời gian sự kiện, hoàn thành thành tựu sự kiện còn có thể nhận được avatar giới hạn sự kiện \"Nhân Danh Chìa Khóa Bạc: Ceyx\", Mệnh Luân SR giới hạn sự kiện \"Ngai Đá Xanh\", Ngân Tâm và lượng lớn tiền tệ sự kiện!\n\n<Title:Thời gian sự kiện>\n1,12 tháng 30 9:00 - 1 tháng 13 9:00(GMT+8)，tất cả lối chơi sự kiện đều có thể tham gia.\n2,1 tháng 13 9:00 - 1 tháng 20 9:00(GMT+8)，chỉ có thể tham gia \"Giác Tri Hải Uyên\" và Phần Thưởng Thành Tựu.\n\n<Title:Ngưng Thị Thâm Hải>\n1,\"Ngưng Thị Thâm Hải\" có 5 màn chơi, mỗi 2 ngày tự động mở 1 màn.\n2, Mỗi lần thử thách sẽ tiêu hao \"Linh Phê Thái\" × 120, thử thách thành công sẽ nhận được tiền tệ sự kiện.\n3, Sau khi thông quan màn chơi, mở khóa chức năng \"Tái Hiện\" của màn đó. Lưu ý: Khi sử dụng chức năng \"Tái Hiện\", không thể nhận được Tỷ Lệ Đồng Điệu.\n4, Có thể sử dụng trợ chiến Hội Cựu Sinh để giúp bạn vượt ải dễ dàng hơn.\n\n<Title:Gia tăng Tự Tư>\n1, Người Giữ Bí Mật sở hữu Thể Thức Tỉnh hoặc Mệnh Luân cụ thể(không yêu cầu ra trận) có thể nhận được bonus rơi thêm tiền tệ sự kiện trong phần thưởng nhiệm vụ màn chơi \"Ngưng Thị Thâm Hải\", chi tiết bonus như sau:\n·Thể Thức Tỉnh \"Turu\": Khải Linh 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n·Mệnh Luân SSR \"Tụng Ca Thần Vương\": Điệp Vị 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n·Mệnh Luân SR \"Ngai Đá Xanh\": Điệp Vị 0/1/2/3 trở lên, bonus 20%/30%/40%/50%.\n2,\"Gia tăng Tự Tư\" của các Thể Thức Tỉnh hoặc Mệnh Luân khác nhau được tính theo phương thức cộng dồn. \n3,Đặc biệt, phần thưởng thông quan lần đầu độ khó Điên Cuồng sẽ không bị ảnh hưởng bởi \"Gia tăng Tự Tư\".\n\n<Title: Giác Tri Hải Uyên>\n1,\"Giác Tri Hải Uyên\" chỉ mở trong khoảng thời gian 30 tháng 12 9:00 - 20 tháng 1 9:00(GMT+8).\n2, Sau 20 tháng 1 9:00(GMT+8)，\"Tự Tư Mệt Mỏi\",\"Tự Tư Bi Sầu\",\"Tự Tư Hoan Duyệt\" chưa đổi sẽ được thu hồi theo tỷ lệ mỗi đơn vị đổi thành \"Phiếu Vàng Tường Vi\" × 40, xin Người Giữ Bí Mật chú ý kiểm tra thư."
  },
