  Activity_77980_ActivityName = {
    Text = "Mạng Lưới Vĩnh Hằng"
  },
  Activity_77980_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian sự kiện \"Mạng Lưới Vĩnh Hằng\" diễn ra, Người Giữ Gìn có thể sử dụng đội hình hệ thống bao gồm Arachne để trải nghiệm màn chơi chỉ định không giới hạn. \n·Khi trải nghiệm màn chơi sự kiện, không thể điều chỉnh thể thức tỉnh trong đội hình. \n<Title:Phần thưởng sự kiện>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng thử nghiệm trên giao diện sự kiện."
