  Activity_78722_ActivityName = {
    Text = "Ám Triều Trùng Minh·Đặt Mua Giới Hạn Thời Gian"
  },
  Activity_78722_ActivityTips = {
    Text = "<Title: Ám Triều Trùng Minh·Mua Trước Giới Hạn>\n·Sự kiện mua trước giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Ám Triều Trùng Minh·Mua Trước Giới Hạn\" mới có thể nhận.\n·Sau khi mua \"Ám Triều Trùng Minh·Mua Trước Giới Hạn\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·\"Ám Triều Trùng Minh·Mua Trước Giới Hạn\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 7 tháng 4."
  },
