  Activity_80311_ActivityName = {
    Text = "Hồi Tưởng Hành Trình Hiến Lễ·Tinh Thần Thiên II"
  },
  Activity_80311_ActivityPlot = {
    Text = "Một đoạn ký ức được niêm phong lưu trữ, một đoạn hành trình được ghi vào quá khứ. Khi truy tư, đừng quên dâng lên lễ vật kính ngưỡng."
  },
  Activity_80312_ActivityName = {
    Text = "Hành trình Điều dưỡng"
  },
  Activity_80312_ActivityTips = {
    Text = "Quy tắc hoạt động:\n1, Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ Kỷ Hành được chỉ định, có thể nhận thưởng trong \"Kỷ Hành Liệu Dưỡng\".\n2,\"Kỷ Hành Liệu Dưỡng\" mở vĩnh viễn.\n3, Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4, Xin lưu ý:\"Kỷ Hành Cao Cấp\"được mở khóa trong hoạt động này chỉ có hiệu lực trong hoạt động này. Xin Người Giữ Bí Mật cân nhắc chi tiêu hợp lý."
  },
  Activity_81019_ActivityName = {
    Text = "Hành Trình Kỳ Diệu Của Việc Dọn Dẹp"
  },
  Activity_81019_ActivityPlot = {
    Text = "Ai đang lướt qua giấc mơ của Kadath, dọn dẹp rác cho chủ nhân?\nLà Karen~ Là Karen!\nDọn dẹp phân rã~ Thông gió mơ~ Khử trùng chiều không gian~ Làm sạch mọi thứ~\nDù sao thì trong lĩnh vực dọn dẹp, Karen tôi là chuyên gia mà!\nChủ nhân có muốn thử không! Karen sẽ dạy không gì giấu diếm cho chủ nhân!"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:Giới thiệu sự kiện>\n1, Trong thời gian sự kiện, người giữ gìn có thể tham gia \"Tiến trình quét dọn\" và nhận \"Công cụ quét dọn\".\n2, Khi tích lũy đủ lượng \"Công cụ quét dọn\", có thể nhận các phần thưởng phong phú trong \"Trợ cấp quét dọn\", bao gồm ảnh đại diện giới hạn sự kiện \"Bậc thầy dọn dẹp\", bạc, lõi thuần khiết, mảnh vỡ đá hiền tài, v. v.\n\n<Title: Tiến trình quét dọn>\n1,\"Tiến trình quét dọn\" bao gồm nhiều loại nhiệm vụ quét dọn khác nhau, người giữ gìn có thể hoàn thành nhiệm vụ quét dọn để nhận \"Công cụ quét dọn\", sau khi hoàn thành tất cả các loại nhiệm vụ quét dọn mỗi ngày sẽ nhận được một phần thưởng bổ sung!\n2, Trong thời gian sự kiện, mỗi lần đầu tiên hoàn thành một loại nhiệm vụ quét dọn sẽ phát sóng cốt truyện ẩn.\n3,\"Tiến trình quét dọn\" sẽ được làm mới và đặt lại vào 9:00 hàng ngày(GMT+8) trong thời gian sự kiện.\n\n<Title: Trợ cấp quét dọn>\n1, Người giữ gìn tích lũy \"Công cụ quét dọn\" sẽ nhận được phần thưởng tương ứng, cứ mỗi 1000 \"Công cụ quét dọn\" sẽ nhận được phần thưởng hàng hóa phong phú, khi tích lũy đạt 10000 \"Công cụ quét dọn\" sẽ nhận được ảnh đại diện độc quyền cho cuộc hành trình quét dọn \"Bậc thầy dọn dẹp\".\n\n<Title: Lời cảm ơn từ Karen>\nTrong thời gian sự kiện, có thể đăng ký tại \"Lời cảm ơn từ Karen\"để nhận những món quà mà Karen đã chuẩn bị cho người giữ gìn!\n\n<Title: Thời gian sự kiện>\nSự kiện này chỉ mở cửa từ 9:00 ngày 28 tháng 4 đến 9:00 ngày 12 tháng 5(GMT+8), sau 9:00 ngày 12 tháng 5(GMT+8) sự kiện sẽ kết thúc, xin các người giữ gìn nhớ nhận thưởng trong \"Trợ cấp quét dọn\"!"
  },
  Activity_81019_BannerText = {
    Text = "Sự kiện đặc biệt đã bắt đầu!"
  },
  Activity_81178_ActivityName = {
    Text = "Trong cơn mưa bão, lay động"
  },
  Activity_81178_ActivityPlot = {
    Text = "Cơn mưa ào ạt đổ xuống từ bầu trời ảm đạm, làm cho mặt biển vang lên âm thanh đập vỡ.\nNhững tia điện không thương tiếc gầm thét, tuyên bố sự xuất hiện khủng khiếp không biên giới dưới mặt biển.\nNautilus rực rỡ như một em bé đang tập đi, yếu ớt lắc lư trong những đợt sóng cuồng loạn.\nKhông ai biết số phận của mình sẽ như thế nào, cũng như con người chỉ có thể nhận thức được sự nhỏ bé của mình khi biển cả đầy biến động thể hiện cơn giận dữ của nó."
  },
  Activity_81178_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc, hiện chỉ có thể tham gia \"Kho báu của thủy thủ\""
  },
  Activity_81178_ActivityTips = {
    Text = "<Title:Giới thiệu sự kiện>\nTrong thời gian sự kiện, Người Giữ Gìn có thể thu thập tiền tệ sự kiện 「Cờ tín hiệu」 thông qua lối chơi giới hạn thời gian 「Mất tích trong đại dương sâu thẳm」 và 「Phần thưởng thành tựu」. 「Cờ tín hiệu」 có thể được đổi thưởng trong 「Báu vật của thuyền viên」, bao gồm SSR độc quyền của sự kiện vòng mệnh 「Hoa tiêu trên biển」, Lõi Lưu Minh, Hạt Nhân Sạch Will, Phân mảnh đá hiền, Tinh thể mịn, v.v...\n\n<Title:Mất tích trong đại dương sâu thẳm>\n1, 「Mất tích trong đại dương sâu thẳm」 bao gồm 9 màn chơi không cần khám phá, trực tiếp chiến đấu sẽ được mở mỗi ngày 1 màn.\n2, Mỗi lần thách đấu sẽ tiêu hao 「Menophin」× 120, khi thách đấu thành công sẽ nhận được nguyên liệu đào tạo và tiền tệ sự kiện.\n3, Sau khi hoàn thành màn chơi, sẽ mở khóa chức năng 「Tái hiện」 của màn đó. Xin lưu ý: Khi sử dụng chức năng 「Tái hiện」, sẽ không nhận được tỷ lệ đồng điều.\n4, Có thể sử dụng sự hỗ trợ của hội cựu sinh viên để giúp bạn dễ dàng hoàn thành màn chơi.\n\n<Title:Hiệu ứng tăng cường Cờ tín hiệu>\n1, Khi Người Giữ Gìn sở hữu các Thể thức tỉnh hoặc vòng mệnh cụ thể (không yêu cầu đội hình xuất chiến), phần thưởng 「Cờ tín hiệu」 trong phần nhiệm vụ màn chơi của 「Mất tích trong đại dương sâu thẳm」 sẽ nhận được tăng cường rơi thêm (bao gồm cả tái hiện), cụ thể như sau:\n· Thể thức tỉnh 「Crépésant」: khởi linh 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%.\n· SSR vòng mệnh 「Thánh hỏa dẫn lối」: Vị trí chồng 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%.\n· SR vòng mệnh 「Hoa tiêu trên biển」: Vị trí chồng 0/1/2/3 trở lên, tăng cường 20%/30%/40%/50%.\n2, Hiệu ứng tăng cường 「Cờ tín hiệu」 của các Thể thức tỉnh hoặc vòng mệnh khác nhau sẽ được tính cộng dồn.\n3, Đặc biệt, phần thưởng thử thách lần đầu trong độ khó điên cuồng sẽ không bị ảnh hưởng bởi các tăng cường trên.\n\n<Title:Báu vật của thuyền viên>\n1, Mỗi lần 「Giao cờ」 sẽ tiêu tốn 750 「Cờ tín hiệu」, nhận ngẫu nhiên năm vật phẩm từ 「Báu vật của thuyền viên」.\n2, Vật phẩm trong 「Báu vật của thuyền viên」 được chia thành hai loại 「Đặc biệt vật phẩm」 và 「Vật phẩm bình thường」. Khi làm mới, lượng vật phẩm đặc biệt còn lại sẽ được đặt lại tới giới hạn tối đa, các quy tắc cụ thể như sau:\n(1)5 lần làm mới đầu tiên: Trường hợp không còn lượng 「Đặc biệt vật phẩm」, Người Giữ Gìn có thể chọn làm mới. Sau khi làm mới, số lượng còn lại của 「Đặc biệt vật phẩm」 và 「Vật phẩm bình thường」 sẽ được đặt lại tới giới hạn tối đa; Ngoài ra, có thể tiếp tục trao đổi. Khi không còn lượng 「Vật phẩm bình thường」 cũng như 「Đặc biệt vật phẩm」, sẽ phải làm mới để tiếp tục trao đổi.\n(2)Lần làm mới từ lần thứ 6 trở đi: Khi không còn lượng 「Vật phẩm bình thường」, mới có thể làm mới. Khi làm mới, số lượng còn lại của 「Vật phẩm bình thường」 sẽ được đặt lại tới giới hạn tối đa, 「Đặc biệt vật phẩm」 sẽ không được đặt lại.\n\n<Title:Thời gian sự kiện>\n1, Từ ngày 5 tháng 5 lúc 9:00 đến ngày 19 tháng 5 lúc 9:00 (GMT+8), có thể tham gia tất cả nội dung đã nêu trong phần giới thiệu sự kiện.\n2, Từ ngày 19 tháng 5 lúc 9:00 đến ngày 26 tháng 5 lúc 9:00 (GMT+8), chỉ giữ lại 「Báu vật của thuyền viên」 và 「Phần thưởng thành tựu」, tất cả nội dung khác đã kết thúc và không thể tham gia.\n3, Sau ngày 26 tháng 5 lúc 9:00 (GMT+8), 「Cờ tín hiệu」 còn lại chưa được đổi sẽ được thu hồi theo tỷ lệ mỗi cái đổi thành 「Vé hoa hồng vàng」× 40. Vui lòng Người Giữ Gìn chú ý kiểm tra hộp thư."
  },
  Activity_81178_BannerText = {
    Text = "Sự kiện chơi game mở cửa trong thời gian giới hạn!"
  },
  Activity_81179_ActivityName = {
    Text = "Cuối cùng dẫn đường"
  },
  Activity_81771_ActivityName = {
    Text = "Nhìn chằm chằm vào bóng tối của vùng đất thần thánh"
  },
  Activity_81771_ActivityPlot = {
    Text = "Không người nào thấy được ánh sáng thánh của Vùng đất thần thánh, nhưng từ sự thật bất ngờ bị rò rỉ, mọi người có thể cảm nhận được bóng tối của Vùng đất thần thánh.\nNó ở đó, luôn ở đó, và vô số tín đồ sẽ biến nó thành hiện thực.\nDù phải phạm phải tội lỗi sâu sắc như thế nào để đổi lấy."
  },
  Activity_81771_ActivityStageEndContent = {
    Text = "Sự kiện đã kết thúc"
  },
  Activity_81771_ActivityTips = {
    Text = "<Title: Dòng triều biến động>\n·\"Dòng triều biến động\" bao gồm 7 màn chơi, 3 màn đầu tiên sẽ được mở vào ngày đầu tiên của sự kiện, sau đó mỗi 3 ngày sẽ mở 1 màn. Mỗi màn chơi đều có phần thưởng phong phú khác nhau!\n·Mỗi loại \"Dòng triều biến động\"đều có rất nhiều cụm, mỗi khi một loại cụm nào đó bị bất kỳ Người Giữ Gìn nào đó thách thức thành công, số lượng cụm của loại \"Dòng triều biến động\"đó sẽ giảm đi 1, khi tất cả các cụm của loại Dòng triều biến động đó bị tiêu diệt, màn chơi tương ứng sẽ bị đóng lại và không thể thách thức lại.\n·Mỗi Người Giữ Gìn có thể đánh bại tối đa 20 lần cụm \"Dòng triều biến động\" mỗi ngày, số lần sẽ được đặt lại vào lúc 9:00 hàng ngày(GMT+8) trong suốt thời gian sự kiện.\n·Mỗi màn chơi sẽ cung cấp các di vật khác nhau, sẽ mang đến cho bạn sức mạnh bổ sung mạnh mẽ.\n·Tất cả các màn chơi đều phải chọn trợ chiến, trong suốt sự kiện, mỗi Người Giữ Gìn có quan hệ theo dõi lẫn nhau chỉ có thể cung cấp trợ chiến cho bạn một lần.\n·Người giữ bí mật cần hoàn thành ít nhất điều tra hành động 2-9 mới có thể tham gia sự kiện này.\n\n<Title: Bồi thường cấp độ>\n·Trong \"Nhìn lén bóng tối của Thần Quốc: Dòng triều biến động\" có cơ chế bồi thường cấp độ, để các Người Giữ Gìn có thể cùng nhau chống lại sự xâm lược!\nQuy tắc bồi thường cấp độ như sau:\n ·Trong đội điều tra, các thể thức tỉnh có cấp độ dưới 60 sẽ được bồi thường lên đến 60 trong thử thách này.\n·Trong đội điều tra, các thể thức tỉnh có cấp độ kỹ năng dưới 5 sẽ được bồi thường lên đến 5 trong thử thách này.\n·Trong đội điều tra, các thể thức tỉnh có\"Điềm báo điên loạn\" dưới 6 sẽ được bồi thường lên đến 6 trong thử thách này.\n·Trong đội điều tra, các thể thức tỉnh có\"Khả năng thích ứng hình thái linh hồn\" dưới 5 sẽ được bồi thường lên đến 5 trong thử thách này.\n ·Nếu Người Giữ Gìn có cấp độ dưới 60, trong thử thách này sẽ được bồi thường lên đến 60.\n\n<Title:Nhiệm vụ giới hạn thời gian>\n·Trong thời gian sự kiện, tích lũy đánh bại 30 lần Dòng triều biến động sẽ hoàn thành nhiệm vụ giới hạn thời gian, nhận được \"Phiếu Vẽ Hình Ảnh Phantu đơn giản(giai đoạn 1)\" ×1!\n·Từ 9:00 ngày 26 tháng 5 đến 9:00 ngày 9 tháng 6(GMT+8), có thể sử dụng \"Phiếu Vẽ Hình Ảnh Phantu đơn giản(giai đoạn 1)\"để đổi lấy trang phục huyền ảo đơn giản tại \"Cửa hàng: Đặt hàng quần áo huyền ảo\".\n·Thêm cách để có được \"Phiếu Vẽ Hình Ảnh Phantu đơn giản(giai đoạn 1)\" có thể tìm hiểu trong cộng đồng và thông báo."
  },
