  Activity_89899_ActivityName = {
    Text = "May Huyễn Y"
  },
  Activity_89899_ActivityTips = {
    Text = "<Title:Giới thiệu sự kiện>\n1, Trong thời gian sự kiện, Người Giữ Bí Mật có thể sử dụng \"Kính Đơn Huyễn Thị\"để rút thưởng. Số lượng \"Kính Đơn Huyễn Thị\" cần thiết cho mỗi lần rút sẽ tăng lên.\n2, Huyễn Y Ngân Xu có cơ hội nhận được từ lần rút thứ 5. Hoàn thành 10 lần rút chắc chắn nhận được Huyễn Y Ngân Xu kỳ hiện tại.\n3, Sau khi sự kiện kết thúc, nếu còn dư\"Kính Đơn Huyễn Thị\" sẽ tự động chuyển đổi thành Nguyên Dịch."
  },
  Activity_89899_BannerText = {
    Text = "Sự kiện rút thưởng giới hạn thời gian khai mở!"
  },
  Activity_90052_ActivityName = {
    Text = "Bộ Não Mục Rữa"
  },
  Activity_90052_ActivityTips = {
    Text = "<Title:Quy tắc hoạt động>\n·Trong thời gian diễn ra hoạt động \"Bộ Não Mục Rữa\", Người Giữ Bí Mật có thể sử dụng đội hình hệ thống có sẵn bao gồm \"Dung Hủy·Doll\"để trải nghiệm màn chơi chỉ định không giới hạn số lần.\n·Khi trải nghiệm màn chơi hoạt động, không thể điều chỉnh Thể Thức Tỉnh trong đội hình.\n<Title:Phần thưởng hoạt động>\n·Sau khi hoàn thành thử thách màn chơi lần đầu, có thể nhận phần thưởng dùng thử tại giao diện hoạt động."
  },
  Activity_90493_ActivityName = {
    Text = "Thực Chiến Giáo Học"
  },
  Activity_90493_ActivityTips = {
    Text = "Quy tắc sự kiện:\n1, Người Giữ Bí Mật có thể học và luyện tập nội dung chiến đấu liên quan trong màn chơi tương ứng.\n2, Khi Người Giữ Bí Mật vượt ải màn chơi Hướng Dẫn Thực Chiến tương ứng, có thể nhận thưởng trong \"Hướng Dẫn Thực Chiến\"."
  },
  Activity_90861_ActivityName = {
    Text = "Mệnh Đồ Liên Hợp"
  },
  Activity_90861_ActivityTips = {
    Text = "<Title: Mệnh Đồ Liên Hợp>\n·Kỷ Hành giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Mệnh Đồ Liên Hợp\" mới có thể nhận.\n·Sau khi mua \"Mệnh Đồ Liên Hợp\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·Mua \"Mệnh Đồ Liên Hợp\" trước 9:00 ngày 20 tháng 4 còn có thể nhận thêm phần thưởng: Avatar chuyên thuộc \"Người Dệt Vận Mệnh\",\"Thiệp Mời Của Vô Hình Giả\" ×10! Sau 9:00 ngày 20 tháng 4 mua sẽ không còn nhận được phần thưởng chuyên thuộc giới hạn. \n· Sau khi mua, thời hạn Kỷ Hành giới hạn lần này sẽ trở thành vĩnh viễn, sau khi nhận hết tất cả gói quà thì ngày hôm sau sự kiện sẽ đóng.\n·\"Mệnh Đồ Liên Hợp\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 18 tháng 5."
  },
  Activity_90861_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
  },
  Activity_90862_ActivityName = {
    Text = "Văn bản tạm thời"
  },
  Activity_90862_ActivityTips = {
    Text = "<Title: Văn Bản Tạm Thời>\n·Sự kiện mua trước giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Văn Bản Tạm Thời\" mới có thể nhận.\n·Sau khi mua \"Văn Bản Tạm Thời\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·\"Văn Bản Tạm Thời\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 7 tháng 4."
  },
  Activity_90862_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
  },
  Activity_90863_ActivityName = {
    Text = "Vạn Nguyện Mô Phỏng"
  },
  Activity_90863_ActivityTips = {
    Text = "<Title: Vạn Nguyện Mô Phỏng>\n·Hành Trình Giới Hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Vạn Nguyện Mô Phỏng\" mới có thể nhận.\n·Sau khi mua \"Vạn Nguyện Mô Phỏng\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần chờ một khoảng thời gian nhất định mới có thể nhận.\n·Mua \"Vạn Nguyện Mô Phỏng\" trước 9:00 ngày 24 tháng 8 còn có thể nhận thêm phần thưởng: Avatar độc quyền \"Mưu Kế Đang Diễn Ra\", \"Lời mời của Vô hình giả\" ×10! Mua sau 9:00 ngày 24 tháng 8 sẽ không còn nhận được phần thưởng độc quyền giới hạn thời gian.\n·\"Vạn Nguyện Mô Phỏng\" có giới hạn thời gian mua, quá hạn sẽ không thể mua nữa. Xin Người giữ bí mật cân nhắc mua trước 9:00 ngày 21 tháng 9, sau khi mua, thời gian kết thúc của Hành Trình Giới Hạn lần này sẽ được kéo dài đến 9:00 ngày 28 tháng 9, để các Người giữ bí mật có đủ thời gian nhận phần thưởng!"
  },
