  Activity_90864_ActivityName = {
    Text = "Tiễn Biệt Lâu Đài Châu Lâu · Hành Trình Giới Hạn"
  },
  Activity_90864_ActivityTips = {
    Text = "<Title: Lô Đình Vãn Ca·Kỷ Hành Giới Hạn>\n·Kỷ Hành giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Lô Đình Vãn Ca·Kỷ Hành Giới Hạn\" mới có thể nhận.\n·Sau khi mua \"Lô Đình Vãn Ca·Kỷ Hành Giới Hạn\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·Mua \"Lô Đình Vãn Ca·Kỷ Hành Giới Hạn\" trước 9:00 ngày 21 tháng 7 còn có thể nhận thêm phần thưởng: Avatar chuyên thuộc \"Ánh Mắt Đói Khát Của Vĩnh Dạ\",\"Thiệp Mời Của Vô Hình Giả\" ×10! Sau 9:00 ngày 21 tháng 7 mua sẽ không còn nhận được phần thưởng chuyên thuộc giới hạn.\n·\"Lô Đình Vãn Ca·Kỷ Hành Giới Hạn\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 18 tháng 8."
