  Activity_90865_ActivityName = {
    Text = "Thai Động Uyên Hải·Hành Trình Giới Hạn"
  },
  Activity_90865_ActivityTips = {
    Text = "<Title: Uyên Hải Thai Động·Kỷ Hành Giới Hạn>\n·Kỷ Hành giới hạn lần này bao gồm 8 gói quà, trong đó gói quà đầu tiên có thể nhận miễn phí trực tiếp, gói quà thứ 2-8 cần mua \"Uyên Hải Thai Động·Kỷ Hành Giới Hạn\" mới có thể nhận.\n·Sau khi mua \"Uyên Hải Thai Động·Kỷ Hành Giới Hạn\" có thể nhận ngay phần thưởng gói quà thứ 2; các gói quà tiếp theo cần đợi một khoảng thời gian nhất định mới có thể nhận.\n·Mua \"Uyên Hải Thai Động·Kỷ Hành Giới Hạn\" trước 9:00 ngày 17 tháng 11 còn có thể nhận thêm phần thưởng: Avatar chuyên thuộc \"Ai Ca Thâm Hải\",\"Thiệp Mời Của Vô Hình Giả\" ×10! Sau 9:00 ngày 17 tháng 11 mua sẽ không còn nhận được phần thưởng chuyên thuộc giới hạn.\n·\"Uyên Hải Thai Động·Kỷ Hành Giới Hạn\" có giới hạn thời gian mua, quá hạn sẽ không thể mua được nữa. Xin Người Giữ Bí Mật cân nhắc mua trước 9:00 ngày 15 tháng 12."
