  Activity_91027_ActivityName = {
    Text = "Cuộc chinh phục vĩ đại"
  },
  Activity_91027_ActivityPlot = {
    Text = "Một thời đại vĩ đại có thể cuối cùng sẽ biến mất, nhưng ý chí của những người chiến đấu vĩ đại sẽ không bao giờ tắt. \nTấm bia không thể chôn vùi họ, xích không thể khuất phục họ. \nKhi con đường mới xuất hiện, bữa tiệc thịt nướng thơm ngon ở cuối con đường chinh phục gọi mời, các chiến binh xông lên, thu thập chiến lợi phẩm vinh quang. \nHãy để chúng ta ca hát vì sự can đảm bất diệt, cho đế chế thiêng liêng này! \nRome! Rome!"
  },
