  Activity_96617_ActivityName = {
    Text = "Mấy Độ Phong Hồng"
  },
  Activity_96617_ActivityTips = {
    Text = "<Title:Quy tắc sự kiện>\n1, Sau khi Người Giữ Bí Mật hoàn thành nhiệm vụ kỷ hành chỉ định, có thể nhận phần thưởng tại \"Mấy Độ Phong Hồng\".\n2,\"Mấy Độ Phong Hồng\" sẽ kết thúc vào 9:00 ngày 23 tháng 3(GMT+8).\n3, Sau khi mở khóa \"Kỷ Hành Cao Cấp\", hoàn thành nhiệm vụ có thể nhận thêm phần thưởng.\n4, Lưu ý: \"Kỷ Hành Cao Cấp\"được mở khóa trong sự kiện này chỉ có hiệu lực trong sự kiện này. Xin Người Giữ Bí Mật cân nhắc chi tiêu hợp lý."
  },
  Activity_96617_BannerText = {
    Text = "Hoạt động Kỷ Hành đặc biệt mở giới hạn thời gian!"
