  Activity_97672_ActivityName = {
    Text = "Lễ hy sinh của sự ra đời của Thần"
  },
  Activity_97672_ActivityPlot = {
    Text = "Không cần phải khóc thương cho quá khứ của món hy sinh lộng lẫy này.\nDâng máu và xương, dâng linh hồn và thịt, dâng tự do, dâng sinh lực.\nCô ấy định mệnh cao quý vô bờ, cô ấy định mệnh đau đớn không nơi nương tựa. Cô ấy là con gái của Thần, cô ấy là mẹ của Thần.\nCô ấy đã vui vẻ chấp nhận số phận đáng sợ và ghê tởm này."
  },
